insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('lars_esbjornsson','lars-esbjornsson','Lars Esbjörnsson',null,'mother',true,false,'public','{"name":"Lars Esbjörnsson","role":"Carls far","status":"confirmed","place":"Tjärby, Grimeton","facts":[["Koppling","Far till Carl Larsson"],["Källa","Carls födelsenotis 1777"]],"story":["Lars Esbjörnsson är bekräftad som Carls far i födelsenotisen 1777.","Släktingens dokument pekade sedan tidigare mot Lars Esbjörnsson från Tjärby i Grimeton. Den aktuella födelsenotisens läsning stärker faderskapet."],"parents":[],"children":["carl_larsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('inger_jonsdotter','inger-jonsdotter','Inger Jonsdotter',null,'mother',true,false,'public','{"name":"Inger Jonsdotter","role":"Carls mor","born":"ca 1743","status":"confirmed","place":"Tjärby, Grimeton","facts":[["Ålder i Carls födelsenotis","34 år"],["Koppling","Mor till Carl Larsson"],["Status","Eget ursprung ej färdigkartlagt"]],"story":["Inger Jonsdotter är bekräftad som Carls mor i födelsenotisen 1777. Där anges hon som 34 år.","Hennes eget ursprung är ännu inte färdigkartlagt."],"parents":[],"children":["carl_larsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('arvid_svensson','arvid-svensson','Arvid Svensson','Arfvid Svensson','mother',true,false,'public','{"name":"Arvid Svensson","alt":"Arfvid Svensson","role":"Bengtas far","born":"ca 1720-11","died":"1785-02-22","status":"confirmed","place":"Munkaskog, Sven Börges gård, Tvååker","facts":[["Begravd","1785-02-24"],["Hemman","1/2 kronohemman nr 5 Munkaskog"],["Civilstånd vid död","Änkling"],["Ålder i dödnotis","64 år, 3 månader, 11 dagar"],["Dödsorsak","Tolkad som hufvudsjuka / huvudvärkssjuka"],["Bouppteckning","1785-03-22"],["Barn","Hans, Anders, Inger, Bengt, Nils och Bengta"]],"story":["Arvid Svensson, även skriven Arfvid Svensson, är Bengtas far enligt födelsenotisen 1774 och är ytterligare stärkt genom bouppteckningen 1785.","Bouppteckningen efter Arfvid Svensson upprättades 22 mars 1785 och gäller mannen på 1/2 kronohemman nr 5 Munkaskog. Den anger barnen med åldrar och binder Bengta till rätt familj och plats.","Boet visar ett etablerat men inte rikt bondehushåll med gårdsdrift, kreatur, textilier, hushållsföremål, bibel och postilla, men även skulder och gravationer."],"timeline":[["ca 1720-11","Född, beräknat från ålder i dödnotis."],["1774-10-20","Dottern Bengta föds i Munkaskog."],["1785-02-22","Dör som änkling i Munkaskog, Sven Börges/Sven Börjes gård."],["1785-02-24","Begravs."],["1785-03-22","Bouppteckning upprättas efter Arfvid Svensson."]],"parents":[],"children":["hans_arfvidsson","anders_arfvidsson","inger_arfvidsdotter","bengt_arfvidsson","nils_arfvidsson","bengta_arvidsdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('elin_bengtsdotter','elin-bengtsdotter','Elin Bengtsdotter',null,'mother',true,false,'public','{"name":"Elin Bengtsdotter","role":"Bengtas mor","born":"ca dec 1732 / jan 1733","died":"1779-03-28","status":"confirmed","place":"Munkaskog, Sven Börges gård, Tvååker","facts":[["Begravd","1779-04-01"],["Civilstånd vid död","Gift"],["Make","Arfvid / Arvid Svensson"],["Ålder i dödnotis","46 år, 3 månader"],["Dödsorsak","Bröstsjuka"],["Koppling","Mor till Bengta Arvidsdotter"]],"story":["Elin Bengtsdotter är bekräftad som Bengtas mor i födelsenotisen 1774.","Dödnotisen anger henne som åboen Arfvid Svenssons hustru i Munkaskog, Sven Börges/Sven Börjes gård. Detta stärker familjegruppen i samma gårdsmiljö.","Elins eget ursprung är ännu inte löst. Nästa steg är att hitta vigseln med Arfvid eller spåra barnens födelsenotiser och faddrar."],"timeline":[["ca 1732/1733","Född, beräknat från ålder i dödnotis."],["1774-10-20","Dottern Bengta föds."],["1779-03-28","Dör i Munkaskog, dödsorsak bröstsjuka."],["1779-04-01","Begravs."]],"parents":[],"children":["hans_arfvidsson","anders_arfvidsson","inger_arfvidsdotter","bengt_arfvidsson","nils_arfvidsson","bengta_arvidsdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
