insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_arfvidsson','bengt-arfvidsson','Bengt Arfvidsson',null,'mother',false,false,'public','{"name":"Bengt Arfvidsson","born":"ca 1768/1769","status":"confirmed","role":"Syskon till Bengta","facts":[["Ålder 1785","16 år"],["Källa","Bouppteckning efter Arfvid Svensson 1785"],["Kommentar","Kan vara samma Bengt som tidigare nämnts som broder Bengt i husförhörsspår"]],"story":["Bengt anges som 16-årig son i bouppteckningen efter Arfvid Svensson. Han kan vara relevant för tidigare spår där en broder Bengt nämns."],"parents":["arvid_svensson","elin_bengtsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_arfvidsson','nils-arfvidsson','Nils Arfvidsson','Nils Arvidsson','mother',false,false,'public','{"name":"Nils Arfvidsson","alt":"Nils Arvidsson","born":"ca 1770/1771","status":"confirmed","role":"Syskon till Bengta","facts":[["Ålder 1785","14 år"],["Källa","Bouppteckning efter Arfvid Svensson 1785"],["Kommentar","Möjlig koppling till tidigare Nils-spår i Munkaskog"]],"story":["Nils anges som 14-årig son i bouppteckningen efter Arfvid Svensson. Detta ger tydligare kontext åt det tidigare Nils-spåret i Munkaskog."],"parents":["arvid_svensson","elin_bengtsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('carl_larsson','carl-larsson','Carl Larsson',null,'mother',true,false,'public','{"name":"Carl Larsson","role":"Anfader i ledet","born":"1777-11-26","died":"ca 1865","status":"confirmed","place":"Rönås, Tvååker","facts":[["Döpt","1777-11-27"],["Födelseplats","Tjärby, Grimeton"],["Yrke","Dräng, saltsjöfiskare, undantagsman"],["Vigsel","1806-03-08, Tvååker (28 år)"]],"story":["Carl föds 26 november 1777 i Tjärby, Grimeton och döps dagen efter. Födelsenotisen anger fadern Lars Esbjörnsson och modern Inger Jonsdotter.","Vid vigseln 1806 står han som dräng i Rönås och anges vara 28 år. Senare återkommer han i Tvååker/Rönås/Ågård-spåret och arbetar bland annat som saltsjöfiskare.","En dödboksnotis 1865 nämner Carl Larsson, undantagsman i Ågård, med ålderdom som dödsorsak."],"timeline":[["1777-11-26","Föds i Tjärby, Grimeton."],["1777-11-27","Döps."],["1806-03-08","Gifter sig med Bengta Arvidsdotter."],["1806-04-15","Sonen Anders föds."],["1865","Trolig död som undantagsman i Ågård."]],"parents":["lars_esbjornsson","inger_jonsdotter"],"children":["anders_carlsson","nils_carlsson","anna_lena_carlsdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengta_arvidsdotter','bengta-arvidsdotter','Bengta Arvidsdotter','Arfvidsdotter','mother',true,false,'public','{"name":"Bengta Arvidsdotter","alt":"Arfvidsdotter","role":"Anmoder i ledet","born":"1774-10-20","status":"confirmed","place":"Munkaskog, Tvååker","facts":[["Döpt","1774-10-23"],["Plats","Munkaskog, Sven Börges gård"],["Vigsel","Piga i Munkaskog (31 år)"],["Bouppteckning","Nämns som 10-årig dotter i Arfvid Svenssons bouppteckning 1785-03-22"],["Syskon","Hans, Anders, Inger, Bengt och Nils"],["Bedömning","Mycket starkt underlag för identifikationen"]],"story":["Bengta föds 20 oktober 1774 och döps tre dagar senare på Sven Börges gård i Munkaskog. Föräldrarna anges som Arfvid/Arvid Svensson och Elin Bengtsdotter.","Bouppteckningen efter Arfvid Svensson 1785 räknar upp en dotter Bengta som 10 år gammal. Det passar mycket väl med Bengta född 1774-10-20 och gör identifikationen mycket stark.","Bengta blev moderlös 1779 och faderlös 1785. Hon växte sannolikt upp i ett etablerat men inte rikt bondhushåll på 1/2 kronohemman nr 5 Munkaskog.","Vid vigseln 1806 är hon piga i Munkaskog och anges vara 31 år."],"timeline":[["1774-10-20","Föds i Munkaskog, Sven Börges gård."],["1774-10-23","Döps."],["1779-03-28","Modern Elin dör."],["1785-02-22","Fadern Arfvid dör."],["1785-03-22","Nämns som 10-årig dotter i bouppteckningen."],["1806-03-08","Gifter sig med Carl Larsson."]],"parents":["arvid_svensson","elin_bengtsdotter"],"children":["anders_carlsson","nils_carlsson","anna_lena_carlsdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_carlsson','nils-carlsson','Nils Carlsson',null,'mother',false,false,'public','{"name":"Nils Carlsson","born":"1809-04-09","status":"confirmed","role":"Syskon","story":["Syskon till Anders, fött 9 april 1809. Grenen är ännu inte utforskad."],"parents":["carl_larsson","bengta_arvidsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_lena_carlsdotter','anna-lena-carlsdotter','Anna Lena Carlsdotter',null,'mother',false,false,'public','{"name":"Anna Lena Carlsdotter","born":"1814-10-13","status":"confirmed","role":"Syskon","story":["Syskon till Anders, född 13 oktober 1814. Grenen är ännu inte utforskad."],"parents":["carl_larsson","bengta_arvidsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anders_carlsson','anders-carlsson','Anders Carlsson',null,'mother',true,false,'public','{"name":"Anders Carlsson","role":"Direkt linje","born":"1806-04-15","status":"confirmed","place":"Rönås, Tvååker","facts":[["Döpt","1806-04-16"],["Yrke","Dräng, tillträdande åbo"],["Vigsel","1834-12-30, No 5 Munkaskog"]],"story":["Anders föds 15 april 1806 i Tvååker som son till Carl Larsson och Bengta Arvidsdotter.","Han står i husförhörslängderna med föräldrarna fram till omkring 1825 och arbetar sedan som dräng på bland annat Munkaskog och Lilla Wråen.","1834 gifter han sig med Johanna Svensdotter och tillträder som åbo i No 5 Munkaskog. Sonen Johan, född 1849, för linjen vidare."],"timeline":[["1806-04-15","Föds i Tvååker."],["1806-04-16","Döps."],["ca 1825","Lämnar föräldrahemmet och börjar arbeta som dräng."],["1825-1834","Dräng på bland annat Munkaskog och Lilla Wråen."],["1834-12-30","Gifter sig med Johanna Svensdotter."],["1849-02-15","Sonen Johan Andersson föds."]],"parents":["carl_larsson","bengta_arvidsdotter"],"children":["lars_august","sven_johan_andersson","christina_andersdotter","bengt_aron_andersson","johan_andersson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johanna_svensdotter','johanna-svensdotter','Johanna Svensdotter',null,'mother',false,false,'public','{"name":"Johanna Svensdotter","role":"Maka","born":"1808-01-12","status":"confirmed","place":"Munkaskog","facts":[["Vigsel","Piga i No 5 Munkaskog (1834)"],["Föräldrar","Äldre linje ej färdigkartlagd"]],"story":["Johanna föds 12 januari 1808 enligt senare uppgifter. Vid vigseln 1834 är hon piga i No 5 Munkaskog.","Hennes äldre föräldralinje är ännu inte färdigkartlagd och bör utforskas separat."],"parents":[],"children":["lars_august","sven_johan_andersson","christina_andersdotter","bengt_aron_andersson","johan_andersson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
