insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johan_andersson','johan-andersson','Johan Andersson',null,'mother',true,false,'public','{"name":"Johan Andersson","role":"Direkt linje","born":"1849-02-15","status":"confirmed","place":"Tvååker","facts":[["Vigsel","1874-09-11, dräng i Grytås"],["Boende","Morups Prästgård / Skillingshagen"]],"story":["Johan föds 15 februari 1849 i Tvååker, son till Anders Carlsson och Johanna Svensdotter.","Vid vigseln 1874 står han som dräng i Grytås. Familjen bor senare vid Morups Prästgård och Skillingshagen."],"parents":["anders_carlsson","johanna_svensdotter"],"children":["augusta_charlotta","birger_johansson","jenny_johansson","karl_hjalmar_johansson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('britta_lovisa','britta-lovisa-carlsdotter','Britta Lovisa Carlsdotter','Karlsdotter','mother',false,false,'public','{"name":"Britta Lovisa Carlsdotter","alt":"Karlsdotter","role":"Maka","born":"1849-05-16","status":"confirmed","place":"trol. Tvååker","facts":[["Vigsel","Piga, trol. Långås No 3"],["Föräldrar","Ej kartlagda i denna linje ännu"]],"story":["Britta Lovisa föds 16 maj 1849, troligen i Tvååker. Vid giftet är hon piga, troligen i Långås No 3."],"parents":[],"children":["augusta_charlotta","birger_johansson","jenny_johansson","karl_hjalmar_johansson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
