insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karl_hjalmar_johansson','karl-hjalmar-johansson','Karl Hjalmar Johansson',null,'mother',true,false,'public','{"name":"Karl Hjalmar Johansson","role":"Direkt linje","born":"1889-06-07","status":"confirmed","place":"Morup","facts":[["Boende","Morup No 5, Skillingshagen"]],"story":["Karl Hjalmar föds 7 juni 1889 i Morup, son till Johan Andersson och Britta Lovisa. Hushållet finns vid Morup No 5, Skillingshagen.","Han och Ester Viktoria får sju kända barn, däribland Karin Margit."],"parents":["johan_andersson","britta_lovisa"],"children":["asta_linnea","elsa_ingegerd","karin_margit","erik_bertil","gosta_ingemar","karl_john_uno","sjunne_lennart"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
