insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karin_margit','karin-margit-johansson','Karin Margit Johansson','g. Bengtsson','mother',true,false,'public','{"name":"Karin Margit Johansson","alt":"g. Bengtsson","role":"Mormor","born":"1929-02-11","died":"2023-10","status":"confirmed","place":"Morup / Klastorp","facts":[["Liv","Flyttade till Klastorp på 1950-talet"],["Avvikelse","Ancestry-skärmbilden visar 1929-2022, men familjeuppgift anger oktober 2023"],["Nästa steg","Komplettera exakt dödsdatum och källa"]],"story":["Karin Margit föds 11 februari 1929 i Morup enligt den senaste morfarsfilen. Hon bär flicknamnet Johansson och tar som gift namnet Bengtsson.","På 1950-talet flyttar hon med Axel Harry Bengtsson till Klastorp. Tillsammans får de barnen Ingemar och Gerd.","Den senaste morfarsfilen anger att familjeuppgiften om död i oktober 2023 ska ges företräde framför Ancestry-trädets 2022-uppgift tills exakt källa kompletteras."],"timeline":[["1929-02-11","Föds i Morup enligt senaste morfarsfilen."],["1950-talet","Flyttar med Harry Bengtsson till Klastorp."],["2023-10","Avlider enligt familjeuppgift; exakt datum ska kompletteras."]],"parents":["karl_hjalmar_johansson","ester_viktoria"],"children":["ingemar_bengtsson","gerd_bengtsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('harry_bengtsson','axel-harry-bengtsson','Axel Harry Bengtsson','Harry Bengtsson','mother',true,false,'public','{"name":"Axel Harry Bengtsson","alt":"Harry Bengtsson","role":"Morfar","born":"1916-12-22","died":"1998","status":"confirmed","place":"Klastorp","facts":[["Födelseort","Klastorp"],["Maka","Karin Margit Johansson"],["Barn","Ingemar och Gerd Bengtsson"],["Föräldrar","Sven Adolf Bengtsson och Gertrud Persdotter"],["Källstatus","Födelsedatum och födelseort finns som arbetsuppgift; originalnotis ska dokumenteras"],["Arrende Valagården","Arrenderade Träslöv 5:7 av farbrodern Lars Emil Bengtsson 1958-04-01–1963-04-01."],["Arrendeavgift","900 kronor per år, betald halvårsvis."],["Brukningsvillkor","Fick använda lada och loge; skulle väl bruka jorden, återställa vall och rensa gränsdiket vartannat år."],["Jordägarens förbehåll","Lars Emil behöll Smedlyckan bakom ladan och svarade för byggnadsunderhållet."]],"story":["Axel Harry Bengtsson föds 22 december 1916 i Klastorp och avlider 1998.","Den senaste morfarsfilen kopplar honom preliminärt till föräldrarna Sven Adolf Bengtsson och Gertrud Persdotter. Födelsenotisen 1916 är prioriterad nästa kontroll för att låsa föräldrarna i originalkälla.","Harry gifter sig med Karin Margit Johansson. Tillsammans får de barnen Ingemar och Gerd Bengtsson.","Ett originalkontrakt från 1958 visar att Harry, då lantbrukare i Klastorp, arrenderade Träslöv 5:7 av sin farbror Lars Emil Bengtsson. Avtalet ger honom en direkt, dokumenterad brukningskoppling till Valagården under efterkrigstiden.","Arrendet löpte i fem år och omfattade jordbruket samt användning av lada och loge. Om avtalet förlängdes efter 1 april 1963 är ännu okänt."],"parents":["sven_adolf_bengtsson","gertrud_persdotter"],"children":["ingemar_bengtsson","gerd_bengtsson"],"timeline":[["1958-03-25","Arrendekontraktet för Träslöv 5:7 undertecknas av jordägaren Emil Bengtsson."],["1958-04-01–1963-04-01","Brukar Valagårdens fastighet Träslöv 5:7 som arrendator."]],"sources":["IMG_6532.HEIC: originalarrendekontrakt mellan Lars Emil Bengtsson och Harry Bengtsson."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('sven_adolf_bengtsson','sven-adolf-bengtsson','Sven Adolf Bengtsson',null,'mother',true,false,'public','{"name":"Sven Adolf Bengtsson","role":"Morfars far","born":"1879","died":"1962","status":"working","facts":[["Maka","Gertrud Persdotter"],["Barn","Axel Harry Bengtsson"],["Föräldrar enligt Ancestry-trädet","Bengt A. Nilsson och Sara Britta Andersdotter"],["Källstatus","Preliminär; födelsenotis och familj ska kontrolleras"],["Bror","Lars Emil Bengtsson, som i handlingarna skrev sig Emil Bengtsson."],["Skuldebrev 1928","Fordringsägare till 3 000 kronor från brodern Lars Emil; Sven Adolf anges bo på nr 12 Klastorp."],["Familjekoppling till Valagården","Brodern Lars Emil bodde på Valagården 1955 och ägde Träslöv 5:7 1958."]],"story":["Sven Adolf Bengtsson förs i senaste morfarsfilen som far till Axel Harry Bengtsson.","Uppgiften kommer från Ancestry-trädet och ska kontrolleras mot födelsenotis, församlingsbok och familjen när Harry föds i Klastorp 1916.","Ett originalskuldebrev daterat 12 november 1928 visar Sven Adolf som fordringsägare när brodern Lars Emil Bengtsson, under namnet Emil Bengtsson, erkände en skuld på 3 000 kronor. Sven Adolf bodde då på nr 12 Klastorp.","Räntan anges i handlingen löpa från 14 mars 1920, åtta år före dateringen. Det kan betyda att 1928 års handling formaliserade ett äldre lån, men detta är ännu en tolkning."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":["harry_bengtsson"],"timeline":[["1928-11-12","Brodern Lars Emil utfärdar ett skuldebrev på 3 000 kronor till Sven Adolf i Klastorp."]],"sources":["anteckning om sven adolf.HEIC: originalskuldebrev daterat 1928-11-12."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('gertrud_persdotter','gertrud-persdotter','Gertrud Persdotter',null,'mother',true,false,'public','{"name":"Gertrud Persdotter","role":"Morfars mor","born":"1875","died":"1951","status":"working","facts":[["Make","Sven Adolf Bengtsson"],["Barn","Axel Harry Bengtsson"],["Källstatus","Preliminär från Ancestry-träd"]],"story":["Gertrud Persdotter förs som mor till Axel Harry Bengtsson i senaste morfarsfilen.","Uppgiften är preliminär tills Harrys födelsenotis och familjens församlingsbok har kontrollerats."],"parents":[],"children":["harry_bengtsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_a_nilsson','bengt-a-nilsson','Bengt A. Nilsson',null,'mother',true,false,'public','{"name":"Bengt A. Nilsson","role":"Morfars farfar","born":"1840","died":"1926","status":"working","facts":[["Maka","Sara Britta Andersdotter"],["Barn","Nils Johan, Anders G., Karl Oskar, Johan Albin, Alma J., Anna V., Sven Adolf och Lars Emil"],["Föräldrar enligt Ancestry-trädet","Nils Bengtsson och Gunnild Alfredsdotter"],["Anmärkning","Mellannamnet bakom initialen A. är ännu okänt"],["Namnform i Valagården-mastern","Bengt August Nilsson; webbplatsens befintliga namnform Bengt A. Nilsson behålls tills fullständigt namn är slutligt samordnat mellan källorna."],["Delägare 1866","Familjens avskrift om Träslöv 5:6 beskriver Bengt August Nilsson som delägare i gårdens byggnader, sannolikt den kvarboende parten."],["Skuldebrev 1901","Lån på 1 600 kronor till J. O. Reis med sex procents ränta; årliga räntebetalningar kan följas 1902-1911."],["Valagård 1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare/uppgiftslämnare för det 12 hektar stora jordbruket."],["Äganderätt","Handlingarna ger stark gårdskoppling men varje historisk mantalsandel och fastighetsdel måste fortfarande hållas isär."]],"story":["Bengt A. Nilsson förs i morfarsfilen som far till Sven Adolf Bengtsson och make till Sara Britta Andersdotter.","Barnaskaran i Ancestry-trädet omfattar åtta kända barn födda mellan 1865 och 1885. Samtliga barns fullständiga datum, födelseorter och koppling till föräldraparet ska kontrolleras.","Valagården-mastern ger Bengt August Nilsson en betydligt tydligare gårdshistoria. Familjens avskrift av förrättningen 1866 beskriver honom som delägare i husen på Träslöv 5:6 och talar sannolikt för att han var den kvarboende parten när Petter Anders Svensson flyttade ut.","Ett skuldebrev från 1901 visar Bengt August under adressen nr 5 Träslöv med en skuld på 1 600 kronor och sex procents ränta. Räntebetalningar är noterade från 1902 till 1911. Säkerheten var indirekt knuten till 3/64 mantal Jöns Nilsgård, men handlingen visar inte ensam att Bengt August ägde just den intecknade andelen.","År 1915 står Bengt Nilsson den äldre som ägare eller uppgiftslämnare för Valagård i lokalundersökningen. Gården omfattade 12 hektar och var nästan helt uppodlad."],"parents":["nils_bengtsson_1814","gunnild_alfredsdotter"],"children":["nils_johan_bengtsson","anders_g_bengtsson","karl_oskar_bengtsson","johan_albin_bengtsson","alma_j_bengtsdotter","anna_v_bengtsdotter","sven_adolf_bengtsson","lars_emil_bengtsson"],"timeline":[["1866-07-04","Familjens avskrift beskriver delning av gårdens byggnader mellan Petter Anders Svensson och Bengt August Nilsson."],["1901-04-04","Utfärdar skuldebrev på 1 600 kronor till J. O. Reis."],["1902-1911","Årliga räntebetalningar antecknas på skuldebrevet."],["1915-08-31","Anges som ägare/uppgiftslämnare för Valagård i lokalundersökningen."]],"sources":["IMG_6524.HEIC och IMG_6525.HEIC: familjeavskrift om byggnadsdelningen 1866.","otydligt.HEIC och otydligt4.HEIC: skuldebrev 1901 och ränteanteckningar 1902-1911.","Lokalundersökningsblankett för Valagård, uppgift lämnad 1915-08-31."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('sara_britta_andersdotter','sara-britta-andersdotter','Sara Britta Andersdotter',null,'mother',true,false,'public','{"name":"Sara Britta Andersdotter","role":"Morfars farmor","born":"1840","died":"1918","status":"working","facts":[["Make","Bengt A. Nilsson"],["Källstatus","Preliminär från Ancestry-träd"],["Valagård 1915","Maken Bengt Nilsson d.ä. står i lokalundersökningens ägarfält; blanketten avgör inte om Sara Britta hade juridisk deläganderätt."]],"story":["Sara Britta Andersdotter förs som maka till Bengt A. Nilsson och mor till Sven Adolf Bengtsson i senaste morfarsfilen.","Uppgifterna är preliminära och behöver kontrolleras i vigselbok, husförhör/församlingsbok och barnens födelsenotiser.","Sara Brittas gårdskoppling till Valagården är etablerad genom hushållet med Bengt August Nilsson. Lokalundersökningen 1915 namnger bara Bengt i ägarfältet, så hennes eventuella juridiska andel lämnas uttryckligen öppen."],"parents":[],"children":["nils_johan_bengtsson","anders_g_bengtsson","karl_oskar_bengtsson","johan_albin_bengtsson","alma_j_bengtsdotter","anna_v_bengtsdotter","sven_adolf_bengtsson","lars_emil_bengtsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_johan_bengtsson','nils-johan-bengtsson','Nils Johan Bengtsson',null,'mother',false,false,'public','{"name":"Nils Johan Bengtsson","role":"Syskon till Sven Adolf","born":"1865","status":"working","story":["Barn till Bengt A. Nilsson och Sara Britta Andersdotter enligt Ancestry-trädet. Fullständigt datum och födelseort ska kontrolleras.","Arvskiftet efter Alma 1955 ger ett direkt belägg för Nils Johans tre döttrar i USA. De maskinskrivna orts- och gatunamnen kan innehålla svenska felskrivningar och behöver kontrolleras mot amerikanska källor."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":[],"facts":[["Barn i USA 1955","Alice Beschel i Illinois, Edna Weltner i Kansas och Esther Sholeen i Illinois anges som döttrar i arvskiftet efter Alma."],["Källkritik","Arvskiftet visar döttrarnas amerikanska bosättning men inte i sig att Nils Johan själv utvandrade."]],"sources":["Arvskifte efter Alma 1955.HEIC."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anders_g_bengtsson','anders-g-bengtsson','Anders G. Bengtsson',null,'mother',false,false,'public','{"name":"Anders G. Bengtsson","role":"Syskon till Sven Adolf","born":"1870","status":"working","story":["Barn till Bengt A. Nilsson och Sara Britta Andersdotter enligt Ancestry-trädet. Initialen G. och fullständiga uppgifter ska kontrolleras."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":[],"facts":[["Amerikaspår","Familjens äldre släktblad markerar sannolikt bostad i Amerika; exakta utvandringsdatum och amerikanska källor saknas."]],"sources":["Familjens äldre släktblad, sekundär migrationskälla."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karl_oskar_bengtsson','karl-oskar-bengtsson','Karl Oskar Bengtsson',null,'mother',false,false,'public','{"name":"Karl Oskar Bengtsson","role":"Syskon till Sven Adolf","born":"1872","status":"working","story":["Barn till Bengt A. Nilsson och Sara Britta Andersdotter enligt Ancestry-trädet. Fullständigt datum och födelseort ska kontrolleras."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":[],"facts":[["Amerikaspår","Familjens äldre släktblad markerar sannolikt bostad i Amerika; exakta utvandringsdatum och amerikanska källor saknas."]],"sources":["Familjens äldre släktblad, sekundär migrationskälla."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johan_albin_bengtsson','johan-albin-bengtsson','Johan Albin Bengtsson',null,'mother',false,false,'public','{"name":"Johan Albin Bengtsson","role":"Syskon till Sven Adolf","born":"1873","status":"working","story":["Barn till Bengt A. Nilsson och Sara Britta Andersdotter enligt Ancestry-trädet. Fullständigt datum och födelseort ska kontrolleras.","Familjens äldre släktblad markerar Johan Albin med bostad i Amerika. Arvskiftet efter Alma ger ett säkert belägg för en bror Albin i Chicago 1955, men identiteten mellan namnformerna lämnas uttryckligen öppen."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":[],"facts":[["Amerikaspår","Arvskiftet 1955 anger Albin Bengtsson på 5707 Dorchester Avenue i Chicago, Illinois."],["Identitetsfråga","Det är mycket möjligt att Albin i arvskiftet är Johan Albin Bengtsson, men namnformen behöver bekräftas i svenska eller amerikanska originalkällor."]],"sources":["Arvskifte efter Alma 1955.HEIC; familjens äldre släktblad, sekundär migrationskälla."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('alma_j_bengtsdotter','alma-j-bengtsdotter','Alma J. Bengtsdotter',null,'mother',false,false,'public','{"name":"Alma J. Bengtsdotter","role":"Syskon till Sven Adolf","born":"1875","died":"1964","status":"working","story":["Barn till Bengt A. Nilsson och Sara Britta Andersdotter enligt Ancestry-trädet. Initialen J. och fullständiga uppgifter ska kontrolleras.","Originalutdraget ur arvskiftet anger namnet Alma Josefina Bengtsson, hemvist Valagården Träslöv 5 och dödsdatum 15 oktober 1954. Webbplatsens äldre arbetsuppgift anger dödsåret 1964. Båda uppgifterna bevaras synligt tills den äldre posten har spårats och konflikten kan avgöras.","Arvskiftet dokumenterar syskonen Albin Bengtsson i Chicago, Anna Viktoria Johansson i Varberg, Sven Adolf Bengtsson i Klastorp och Lars Emil Bengtsson på Valagården. Även tre döttrar efter den avlidne brodern Nils Johan bodde i USA."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":[],"facts":[["Fullständigt namn i arvskiftet","Alma Josefina Bengtsson."],["Motstridigt dödsår","Webbplatsen har sedan tidigare 1964. Originalutdraget ur arvskiftet anger 1954-10-15; inget raderas innan uppgifterna har samordnats."],["Hemvist","Valagården, Träslöv 5 enligt arvskiftesutdraget."],["Arvskifte","Förrättat 1955-01-12; namnger fyra kvarlevande syskon och tre amerikanska brorsdöttrar."]],"timeline":[["1954-10-15","Avlider enligt originalutdraget ur arvskiftet; detta strider mot webbplatsens äldre arbetsår 1964."],["1955-01-12","Arvskifte förrättas och dokumenterar familjens svenska och amerikanska grenar."]],"sources":["Arvskifte efter Alma 1955.HEIC: originalutdrag ur arvskiftesinstrumentet."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_v_bengtsdotter','anna-v-bengtsdotter','Anna V. Bengtsdotter',null,'mother',false,false,'public','{"name":"Anna V. Bengtsdotter","role":"Syskon till Sven Adolf","born":"1876","died":"1967","status":"working","story":["Barn till Bengt A. Nilsson och Sara Britta Andersdotter enligt Ancestry-trädet. Initialen V. och fullständiga uppgifter ska kontrolleras."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":[],"facts":[["Arvskiftet 1955","Anna Viktoria Johansson, född Bengtsdotter, bodde på Påskbergsvägen 4 i Varberg och närvarade vid arvskiftet efter systern Alma."],["Syskonbelägg","Originalutdraget bekräftar syskonrelationen till Albin, Sven Adolf, Lars Emil, Alma och den avlidne Nils Johan."]],"sources":["Arvskifte efter Alma 1955.HEIC."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('lars_emil_bengtsson','lars-emil-bengtsson','Lars Emil Bengtsson',null,'mother',false,false,'public','{"name":"Lars Emil Bengtsson","role":"Syskon till Sven Adolf","born":"1885","died":"1965","status":"working","story":["Barn till Bengt A. Nilsson och Sara Britta Andersdotter enligt Ancestry-trädet. Fullständigt datum och födelseort ska kontrolleras.","Lars Emil Bengtsson framträder i Valagården-mastern genom tre originalhandlingar. I skuldförbindelsen 1928 skriver han sig Emil Bengtsson, nr 5 Träslöv, och erkänner en skuld på 3 000 kronor till brodern Sven Adolf.","Arvskiftet efter systern Alma 1955 anger Lars Emil bosatt på Valagården. Tre år senare skriver han som jordägare under ett arrendekontrakt där hans fastighet Träslöv 5:7 upplåts till brorsonen Harry Bengtsson.","Arrendet omfattade jord samt användning av lada och loge. Lars Emil behöll Smedlyckan bakom ladan och ansvarade själv för byggnadsunderhållet."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":[],"facts":[["Namn i handlingar","Emil Bengtsson; identiteten som Lars Emil är familjebekräftad och stöds av arvskiftet 1955."],["Adress 1928","Nr 5 Träslöv."],["Skuld 1928","3 000 kronor till brodern Sven Adolf Bengtsson med fem procents ränta, angiven från 1920-03-14."],["Bosättning 1955","Arvskiftet efter Alma anger honom på Valagården i Träslöv."],["Ägare 1958","Originalkontraktet anger honom som ägare till Träslöv 5:7."],["Arrendator","Brorsonen Harry Bengtsson arrenderade fastigheten 1958-04-01–1963-04-01 för 900 kronor per år."]],"timeline":[["1928-11-12","Under namnet Emil Bengtsson utfärdar han skuldebrev till brodern Sven Adolf."],["1955-01-12","Arvskiftet efter Alma placerar honom på Valagården i Träslöv."],["1958-03-25","Undertecknar arrendekontrakt som ägare till Träslöv 5:7."],["1958-04-01–1963-04-01","Arrenderar ut fastigheten till brorsonen Harry Bengtsson."]],"sources":["anteckning om sven adolf.HEIC: originalskuldebrev daterat 1928-11-12.","Arvskifte efter Alma 1955.HEIC.","IMG_6532.HEIC: originalarrendekontrakt daterat 1958-03-25."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_bengtsson_1814','nils-bengtsson','Nils Bengtsson',null,'mother',true,false,'public','{"name":"Nils Bengtsson","role":"Morfars farfars far","born":"1814-05-11","status":"confirmed","place":"Wahlagården, Träslöv","facts":[["Döpt","1814-05-12"],["Far","Bengt Olofsson, åbo"],["Mor","Bengta Börgesdotter/Börjesdotter"],["Källa","Träslöv CI:5 (1799-1825), Bild 109 / Sida 211"],["Källstatus","Originalbild och ArkivDigitals födelsepost kontrollerade"],["Avvikelse löst","Rätt datum är 1814-05-11, inte 1814-06-11"]],"story":["Nils Bengtsson föds 11 maj 1814 och döps dagen därpå i Träslöv.","Födelsenotisen anger föräldrarna åbon Bengt Olofsson och Bengta Börgesdotter samt placerar familjen vid Wahlagården. Detta visar att familjen fanns där redan i maj 1814.","Nils förs som far till Bengt A. Nilsson enligt Ancestry-trädet, men vigseln med Gunnild Alfredsdotter och vidare hushållskopplingar ska fortfarande kontrolleras."],"timeline":[["1814-05-11","Föds vid Wahlagården i Träslöv."],["1814-05-12","Döps."],["1840","Sonen Bengt A. Nilsson föds enligt Ancestry-trädet."]],"parents":["bengt_olofsson_1784","bengta_borjesdotter_1793"],"children":["bengt_a_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('gunnild_alfredsdotter','gunnild-alfredsdotter','Gunnild Alfredsdotter',null,'mother',true,false,'public','{"name":"Gunnild Alfredsdotter","role":"Morfars farfars mor","born":"1809","died":"1860","status":"working","facts":[["Make","Nils Bengtsson"],["Källstatus","Preliminär; stavning och patronymikon ska kontrolleras mot originalkälla"]],"story":["Gunnild Alfredsdotter förs i senaste morfarsfilen som maka till Nils Bengtsson och mor till Bengt A. Nilsson.","Stavningen återges från Ancestry-trädet och behöver kontrolleras mot originalkällor."],"parents":[],"children":["bengt_a_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_olofsson_1784','bengt-olofsson','Bengt Olofsson','Bengt Olsson','mother',true,false,'public','{"name":"Bengt Olofsson","alt":"Bengt Olsson","role":"Morfars farfars farfar","born":"1784-08-10","status":"confirmed","place":"Olof Svensgård / Wahlagården, Träslöv","facts":[["Döpt","1784-08-12"],["Födelseplats","Olof Svensgård, Träslöv"],["Vigsel","1813-12-26 med Bengta Börjesdotter i Träslöv"],["Titel vid vigsel","Åbo och dräng"],["Föräldrar","Olof Nilsson och Karin Svensdotter"],["Källstatus","Födelse/dop, vigsel och husförhör kontrollerade"]],"story":["Bengt Olofsson föds 10 augusti 1784 vid Olof Svensgård i Träslöv och döps 12 augusti. Födelsenotisen anger föräldrarna Olof Nilsson och Karin Svensdotter.","Han vigs 26 december 1813 med Bengta Börjesdotter, piga från Wahlagården. Den starkaste arbetshypotesen är att Bengt kom till Wahlagården genom äktenskapet med Bengta.","Paret får minst nio barn enligt Träslövs födelseindex. Flera originalnotiser återstår att kontrollera, men Nils 1814 och Anders 1816 är särskilt viktiga för gårdskontinuiteten."],"timeline":[["1784-08-10","Föds vid Olof Svensgård, Träslöv."],["1813-12-26","Vigs med Bengta Börjesdotter från Wahlagården."],["1814-05-11","Sonen Nils föds vid Wahlagården."],["1816-02-14","Sonen Anders föds vid Träslöfs Wahlagården."]],"parents":["olof_nilsson_1750","karin_svensdotter_1741"],"children":["nils_bengtsson_1814","anders_bengtsson_1816","karin_bengtsdotter_1818","olena_bengtsdotter_1820","anna_beata_bengtsdotter","bengt_bengtsson_1825","par_bengtsson","anders_peter_bengtsson","anna_bengtsdotter_1831"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengta_borjesdotter_1793','bengta-borjesdotter','Bengta Börjesdotter','Börgesdotter','mother',true,false,'public','{"name":"Bengta Börjesdotter","alt":"Börgesdotter","role":"Morfars farfars farmor","born":"1793-10-25","status":"confirmed","place":"Wahlagården, Träslöv","facts":[["Döpt","1793-10-27"],["Far","Börje Pehrsson"],["Mor","Anna Olofsdotter"],["Vigsel","1813-12-26 med Bengt Olofsson"],["Moderns ålder vid Bengtas födelse","26 år"],["Källa","Träslöv CI:4 (1747-1798), Bild 1630 / Sida 311"],["Källstatus","Födelse- och dopnotis hittad; Ancestrys 1797-uppgift avförd"]],"story":["Bengta Börjesdotter föds 25 oktober 1793 och döps 27 oktober i Träslöv. Födelsenotisen anger föräldrarna bonden Börje Pehrsson och Anna Olofsdotter.","Hennes födelsedatum löser den tidigare ålderskonflikten: i sonen Anders födelsenotis 1816 anges modern vara 22 år, vilket passar 1793 men inte Ancestrys 1797.","Vid vigseln 1813 anges Bengta som piga från Wahlagården. Det gör henne till den sannolika länken in i Wahlagården/Jon Nilsgård-spåret."],"parents":["borje_pehrsson","anna_olofsdotter_1767"],"children":["nils_bengtsson_1814","anders_bengtsson_1816","karin_bengtsdotter_1818","olena_bengtsdotter_1820","anna_beata_bengtsdotter","bengt_bengtsson_1825","par_bengtsson","anders_peter_bengtsson","anna_bengtsdotter_1831"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anders_bengtsson_1816','anders-bengtsson','Anders Bengtsson',null,'mother',false,false,'public','{"name":"Anders Bengtsson","role":"Syskon till Nils Bengtsson","born":"1816-02-14","status":"confirmed","place":"Träslöfs Wahlagården","facts":[["Döpt","1816-02-15"],["Far","Bengt Olofsson"],["Mor","Bengta Börgesdotter"],["Moderns ålder","22 år"],["Källa","Träslöv CI:5 (1799-1825), Bild 130 / Sida 251"],["Källstatus","Originalnotis kontrollerad"]],"story":["Anders föds 14 februari 1816 och döps 15 februari. Originalnotisen anger uttryckligen Träslöfs Wahlagården.","Notisen stärker gårdskontinuiteten från Bengtas vigsel 1813 och Nils födelse 1814."],"parents":["bengt_olofsson_1784","bengta_borjesdotter_1793"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karin_bengtsdotter_1818','karin-bengtsdotter','Karin Bengtsdotter',null,'mother',false,false,'public','{"name":"Karin Bengtsdotter","role":"Syskon till Nils Bengtsson","born":"1818-01-01","status":"working","place":"John Nilsgård, Träslöv","facts":[["Födelseort enligt index","Träslöf John Nilsgård"],["Källstatus","Indexpost; originalnotis återstår"]],"story":["Karin förs som barn till Bengt Olofsson och Bengta Börjesdotter enligt Träslövs födelseindex. Platsen anges som John/Jon Nilsgård, vilket i morfarsfilen behandlas som samma gårdsenhet som Wahlagården."],"parents":["bengt_olofsson_1784","bengta_borjesdotter_1793"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
