insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anders_peter_bengtsson','anders-peter-bengtsson','Anders Peter Bengtsson',null,'mother',false,false,'public','{"name":"Anders Peter Bengtsson","role":"Syskon till Nils Bengtsson","born":"1831-07-03","status":"working","place":"Träslöv","facts":[["Tvilling","Sannolikt tvilling med Anna, samma födelsedatum"],["Källstatus","Indexpost; originalnotis återstår"]],"story":["Anders Peter förs som barn till Bengt Olofsson och Bengta Börjesdotter enligt Träslövs födelseindex. Han har samma födelsedatum som Anna och är därför sannolikt tvilling, vilket ska bekräftas i originalnotisen."],"parents":["bengt_olofsson_1784","bengta_borjesdotter_1793"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_bengtsdotter_1831','anna-bengtsdotter','Anna Bengtsdotter',null,'mother',false,false,'public','{"name":"Anna Bengtsdotter","role":"Syskon till Nils Bengtsson","born":"1831-07-03","status":"working","place":"Träslöv","facts":[["Tvilling","Sannolikt tvilling med Anders Peter, samma födelsedatum"],["Källstatus","Indexpost; originalnotis återstår"]],"story":["Anna förs som barn till Bengt Olofsson och Bengta Börjesdotter enligt Träslövs födelseindex. Hon har samma födelsedatum som Anders Peter och är därför sannolikt tvilling, vilket ska bekräftas i originalnotisen."],"parents":["bengt_olofsson_1784","bengta_borjesdotter_1793"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('borje_pehrsson','borje-pehrsson','Börje Pehrsson',null,'mother',true,false,'public','{"name":"Börje Pehrsson","role":"Bengta Börjesdotters far","status":"confirmed","place":"Klastorps Buragård / Jon Nilsgård, Träslöv","facts":[["Titel","Dräng vid vigseln, senare bonde"],["Vigsel","1790-12-26 med Anna Olofsdotter"],["Hemort vid vigsel","Klastorps Buragård"],["Bostad efter vigsel","N:o 5 Jon Nilsgård"],["Dotter","Bengta Börjesdotter, född 1793-10-25"],["Källor","Träslöv CI:4 Bild 1230 / Sida 233; CI:4 Bild 1630 / Sida 311; AI:3 Bild 85 / Sida 111"]],"story":["Börje Pehrsson är dokumenterad som far till Bengta Börjesdotter i hennes födelse- och dopnotis 1793.","Vigselnotisen 1790 visar att Börje var dräng från Klastorps Buragård när han gifte sig med Anna Olofsdotter från Träslöf Valagård. Därmed kom han in i Valagårdsmiljön genom äktenskapet med Anna.","Ett husförhör placerar Börje och Anna vid N:o 5 Jon Nilsgård tillsammans med sonen Pehr. Det stärker kedjan från Jon Nilsgård/Valagård till Bengta och vidare till Bengt Olofsson."],"timeline":[["1790-12-26","Vigs med Anna Olofsdotter från Träslöf Valagård."],["1787-1800","Återfinns i hushåll vid N:o 5 Jon Nilsgård."],["1793-10-25","Dottern Bengta föds i Träslöv."]],"parents":[],"children":["bengta_borjesdotter_1793"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_olofsdotter_1767','anna-olofsdotter','Anna Olofsdotter',null,'mother',true,false,'public','{"name":"Anna Olofsdotter","role":"Bengta Börjesdotters mor","born":"1767-06-17","status":"confirmed","place":"Jon Nilsgård / Valagård, Träslöv","facts":[["Döpt","1767-06-21"],["Far","Olof Andersson"],["Mor","Anna Mårtensdotter"],["Vigsel","1790-12-26 med Börje Pehrsson"],["Hemort vid vigsel","Träslöf Valagård"],["Bostad som vuxen","N:o 5 Jon Nilsgård"],["Ålder vid Bengtas födelse","26 år"],["Källa","Träslöv CI:4 (1747-1798), Bild 490 / Sida 87"]],"story":["Anna Olofsdotter föds 17 juni 1767 vid Jon Nilsgård i Träslöv och döps 21 juni. Originalnotisen anger föräldrarna Olof Andersson och Anna Mårtensdotter.","Vid vigseln 1790 anges Anna som piga från Träslöf Valagård, medan Börje Pehrsson kommer från Klastorps Buragård. Det visar att gårdskopplingen i denna generation går genom Anna.","Husförhöret vid N:o 5 Jon Nilsgård placerar Anna och Börje i samma gårdsmiljö som Annas föräldrar, vilket gör gårdskedjan genom Bengta Börjesdotters mödernelinje mycket stark."],"timeline":[["1767-06-17","Föds vid Jon Nilsgård, Träslöv."],["1767-06-21","Döps."],["1790-12-26","Vigs med Börje Pehrsson."],["1793-10-25","Dottern Bengta föds."]],"parents":["olof_andersson_jon_nilsgard","anna_martensdotter_jon_nilsgard"],"children":["bengta_borjesdotter_1793"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('olof_andersson_jon_nilsgard','olof-andersson','Olof Andersson',null,'mother',true,false,'public','{"name":"Olof Andersson","role":"Anna Olofsdotters far","status":"confirmed","place":"Dagsås / Jon Nilsgård, Träslöv","facts":[["Hustru","Anna Mårtensdotter"],["Vigsel","1765-02-10 med Anna Mårtensdotter från Träslöv Jön Nilsgård"],["Hemort vid vigsel","Dagsås"],["Dotter","Anna Olofsdotter, född 1767-06-17"],["Ålder i husförhör","56 år"],["Bostad","N:o 5 Jon Nilsgård"],["Källor","Träslöv CI:4 Bild 1180 / Sida 223; CI:4 Bild 490 / Sida 87; Träslöv AI:3 Bild 85 / Sida 111"]],"story":["Olof Andersson gifter sig 10 februari 1765 med Anna Mårtensdotter från Träslöv Jön Nilsgård. Vigselnotisen anger honom som dräng från Dagsås, vilket visar att han kom in i gårdsmiljön genom äktenskapet.","Han är bekräftad som far till Anna Olofsdotter i hennes födelse- och dopnotis 1767 och återfinns senare i hushållet vid N:o 5 Jon Nilsgård."],"timeline":[["1765-02-10","Vigs med Anna Mårtensdotter från Träslöv Jön Nilsgård."],["1767-06-17","Dottern Anna Olofsdotter föds vid Jon Nilsgård."],["1787-1800","Återfinns i hushållet vid N:o 5 Jon Nilsgård."]],"parents":[],"children":["anna_olofsdotter_1767"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_martensdotter_jon_nilsgard','anna-martensdotter','Anna Mårtensdotter',null,'mother',true,false,'public','{"name":"Anna Mårtensdotter","role":"Anna Olofsdotters mor","born":"1732-04-24","status":"confirmed","place":"Jöns/Jon Nilsgård, Träslöv","facts":[["Döpt","1732-04-28"],["Far","Mårten Andersson"],["Mor","Helena Jönsdotter"],["Vigsel","1765-02-10 med Olof Andersson från Dagsås"],["Ålder i Mårtens bouppteckning 1762","ca 30 år"],["Källstatus","Födelsenotis, vigselnotis och bouppteckning bekräftar identiteten"],["Gårdsövergång","Piga från Jön Nilsgård vid vigseln 1765; maken Olof Andersson kom från Dagsås."],["Källvärde","Mårtens bouppteckning 1762 nämner en dotter Anna, 30 år, vilket passar födelsen 1732."]],"story":["Anna Mårtensdotter föds 24 april 1732 och döps 28 april. Födelsenotisen anger föräldrarna Mårten Andersson och Helena Jönsdotter.","Mårten Anderssons bouppteckning 1762 nämner dottern Anna, cirka 30 år, vilket stämmer med födelsenotisen 1732. Vid vigseln 1765 anges Anna som piga från Träslöv Jön Nilsgård.","Genom Anna går den källbelagda gårdskedjan vidare från Mårten och Helena till dottern Anna Olofsdotter och senare Bengta Börjesdotter."],"timeline":[["1732-04-24","Föds i Träslöv."],["1732-04-28","Döps."],["1762-10-21","Nämns som dotter, ca 30 år, i Mårten Anderssons bouppteckning."],["1765-02-10","Vigs med Olof Andersson från Dagsås."],["1767-06-17","Dottern Anna Olofsdotter föds vid Jon Nilsgård."]],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":["anna_olofsdotter_1767"],"sources":["Träslöv födelse- och dopbok 1732, originalsid 65; Träslöv (N) CI:4, Bild 1180 / Sida 223."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('marten_andersson_1701','marten-andersson','Mårten Andersson',null,'mother',true,false,'public','{"name":"Mårten Andersson","role":"Anna Mårtensdotters far","born":"ca 1701","died":"1762-07-27","status":"confirmed","place":"Jöns/Jon Nilsgård, Träslöv","facts":[["Begravd","1762-08-01"],["Dödsorsak","Bröstfeber"],["Bouppteckning","1762-10-21, Himle häradsrätt FIIb:3, Sida 9"],["Make","Helena Jönsdotter"],["Barn","Anna, Börta, Kerstin, Nils, Karin, Jöns, Anders och Börje"],["Källstatus","Dödsnotis och bouppteckning placerar honom vid Jöns Nilsgård"],["Vigselnotis 1731","Mårten anges som dräng i Träslöfs by; notisen innehåller inget säkert Valagårdsbelägg."],["Husförhör ca 1756-1759","Mårtens familj står under gårdsrubriken Jon Nilsgård tillsammans med ett separat hushåll för Börge Andersson."],["Korrigerad läsning","Den femåriga personen i N:o 42-materialet omkring 1700 är Kirsti/Kerstin Andersdotter, inte Mårten Andersson."]],"story":["Mårten Andersson dör 27 juli 1762 vid Jöns Nilsgård i Träslöv och begravs 1 augusti. Åldern pekar mot födelse omkring 1701.","Bouppteckningen efter Mårten förrättades 21 oktober 1762 och nämner änkan Helena Jönsdotter samt åtta barn. Dottern Anna, cirka 30 år, binder honom till Anna Mårtensdotter född 1732.","Hans födelseort och föräldrar är ännu inte originalbekräftade. Nygård-spåret och en möjlig Mårten Andersson i tidiga gårdslistor ska fortsatt prövas källkritiskt.","Valagården-mastern avgränsar den säkra gårdskopplingen noggrant: vigseln 1731 visar bara Mårten som dräng i Träslöfs by. Husförhöret omkring 1756-1759 och originalhandlingarna från 1762 ger däremot starka belägg för familjen vid Jon/Jöns Nilsgård."],"timeline":[["1731-04-25","Vigs med Helena Jönsdotter."],["1732-04-24","Dottern Anna Mårtensdotter föds."],["1762-07-27","Dör vid Jöns Nilsgård av bröstfeber."],["1762-08-01","Begravs."],["1762-10-21","Bouppteckning förrättas efter honom."]],"parents":[],"children":["anna_martensdotter_jon_nilsgard","borta_martensdotter","kerstin_martensdotter","nils_martensson_1740","karin_martensdotter","jons_martensson","anders_martensson","borje_martensson"],"sources":["Träslöv (N) CI:4, Bild 1410 / Sida 267; Himle häradsrätt FIIb:3, originalsid 9."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('helena_jonsdotter_1713','helena-jonsdotter','Helena Jönsdotter','Helen','mother',true,false,'public','{"name":"Helena Jönsdotter","alt":"Helen","role":"Anna Mårtensdotters mor","born":"1713-10-07","died":"1800-05-29","status":"confirmed","place":"Klockaregården / Skultagården / Jöns Nilsgård, Träslöv","facts":[["Född","mellan 6 och 7 oktober 1713"],["Döpt","1713-10-08"],["Far","Jöns/Jonas Andersson Polin, klockaren"],["Mor","Kari/Karin Helgesdotter"],["Faddrar","Bland annat Jöns Grimberg, Mathias Höök, Olof Börgesson i Lunden, Anders Gillberg/Cillberg, Elisabet Bruhn och personer från Varberg; möjlig Agneta Bolin/Polin ska kontrolleras"],["Vigsel","1731-04-25 med Mårten Andersson"],["Hemvist vid vigsel","Skultagården"],["Bouppteckning","1800-10-13 vid N:o 5 Jon Nilsgård"],["Källstatus","Födelse/dop, vigsel och bouppteckning är starkt belagda; fadderläsningarna är delvis preliminära"],["Valagårdskoppling","Vigseln 1731 anger Skultagården, inte Valagården. Bouppteckningen 1800 placerar henne däremot vid N:o 5 Jon Nilsgård."],["Åldersskillnad i Valagården-mastern","Personöversikten återger den äldre sekundära uppskattningen omkring 1709, medan den befintliga originaltolkningen anger födelse 1713-10-06/07. Båda uppgifterna bevaras med olika källstatus."]],"story":["Helena Jönsdotter föds under natten mellan 6 och 7 oktober 1713 och döps 8 oktober i Träslöv. Födelsenotisen anger henne som klockarens dotter, vilket i sammanhanget binder henne till Jöns/Jonas Andersson Polin och Karin Helgesdotter.","Fadderkretsen är ovanligt intressant: den innehåller ämbetsmannamässiga namn, personer från Varberg och Lunden samt en möjlig Polin/Bolin-person. Det passar väl med Jöns Polins roll som klockare och hans Varbergskoppling.","Vid vigseln med Mårten Andersson 1731 anges Helena som piga från Skultagården. Det visar hemvist vid vigseln, men inte säkert födelsegård.","Bouppteckningen efter Helena 1800 placerar henne vid N:o 5 Jon Nilsgård och nämner dottern Anna, gift med Olof Andersson. Det ger ytterligare stöd för Valagård/Jon Nilsgård-kedjan.","Valagården-masterns personöversikt återger en äldre ungefärlig födelsetid omkring 1709. Webbplatsens redan publicerade uppgift 1713 bygger på den starkare födelse- och dopnotisen och behålls; avvikelsen dokumenteras i stället för att jämnas ut."],"timeline":[["1713-10-06/07","Föds under natten mellan 6 och 7 oktober."],["1713-10-08","Döps i Träslöv."],["1731-04-25","Vigs med Mårten Andersson och anges som piga från Skultagården."],["1800-05-29","Dör sannolikt enligt bouppteckningen."],["1800-10-13","Bouppteckning förrättas vid N:o 5 Jon Nilsgård."]],"parents":["jons_polin_1682","karin_helgesdotter_1685"],"children":["anna_martensdotter_jon_nilsgard","borta_martensdotter","kerstin_martensdotter","nils_martensson_1740","karin_martensdotter","jons_martensson","anders_martensson","borje_martensson"],"sources":["Himle häradsrätt FIIa:11 (1800-1802), bouppteckning efter Helena Jönsdotter."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('borta_martensdotter','borta-martensdotter','Börta Mårtensdotter',null,'mother',false,false,'public','{"name":"Börta Mårtensdotter","role":"Syskon till Anna Mårtensdotter","born":"ca 1736","status":"confirmed","place":"Jöns/Jon Nilsgård, Träslöv","facts":[["Ålder i bouppteckning 1762","ca 26 år"],["Källstatus","Bouppteckning efter Mårten Andersson"]],"story":["Börta räknas upp som barn i bouppteckningen efter Mårten Andersson vid Jöns Nilsgård 1762."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('kerstin_martensdotter','kerstin-martensdotter','Kerstin Mårtensdotter',null,'mother',false,false,'public','{"name":"Kerstin Mårtensdotter","role":"Syskon till Anna Mårtensdotter","born":"ca 1738","status":"confirmed","place":"Jöns/Jon Nilsgård, Träslöv","facts":[["Ålder i bouppteckning 1762","ca 24 år"],["Källstatus","Bouppteckning efter Mårten Andersson"]],"story":["Kerstin räknas upp som barn i bouppteckningen efter Mårten Andersson vid Jöns Nilsgård 1762."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_martensson_1740','nils-martensson','Nils Mårtensson',null,'mother',false,false,'public','{"name":"Nils Mårtensson","role":"Syskon till Anna Mårtensdotter","born":"ca 1740","status":"likely","place":"Valagård / Jöns Nilsgård, Träslöv","facts":[["Ålder i bouppteckning 1762","ca 22 år"],["Sekundär uppgift","Leif Lundquist anger född 1740-08-08 vid Valagård"],["Källstatus","Bouppteckning + sekundär uppgift"]],"story":["Nils räknas upp som barn i bouppteckningen efter Mårten Andersson. Leif Lundquists antavla anger födelsedatumet 1740-08-08 vid Valagård, vilket bör kontrolleras i original."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karin_martensdotter','karin-martensdotter','Karin Mårtensdotter',null,'mother',false,false,'public','{"name":"Karin Mårtensdotter","role":"Syskon till Anna Mårtensdotter","born":"ca 1741","status":"confirmed","place":"Jöns/Jon Nilsgård, Träslöv","facts":[["Ålder i bouppteckning 1762","ca 21 år"],["Källstatus","Bouppteckning efter Mårten Andersson"]],"story":["Karin räknas upp som barn i bouppteckningen efter Mårten Andersson vid Jöns Nilsgård 1762."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
