insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anders_martensson','anders-martensson','Anders Mårtensson',null,'mother',false,false,'public','{"name":"Anders Mårtensson","role":"Syskon till Anna Mårtensdotter","born":"ca 1751","status":"confirmed","place":"Jöns/Jon Nilsgård, Träslöv","facts":[["Ålder i bouppteckning 1762","ca 11 år"],["Källstatus","Bouppteckning efter Mårten Andersson"]],"story":["Anders räknas upp som barn i bouppteckningen efter Mårten Andersson vid Jöns Nilsgård 1762."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('borje_martensson','borje-martensson','Börje Mårtensson',null,'mother',false,false,'public','{"name":"Börje Mårtensson","role":"Syskon till Anna Mårtensdotter","born":"ca 1754","status":"confirmed","place":"Jöns/Jon Nilsgård, Träslöv","facts":[["Ålder i bouppteckning 1762","ca 8 år"],["Källstatus","Bouppteckning efter Mårten Andersson"]],"story":["Börje räknas upp som barn i bouppteckningen efter Mårten Andersson vid Jöns Nilsgård 1762."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('jons_polin_1682','jons-jonas-andersson-polin','Jöns/Jonas Andersson Polin','Polijn / Paulin','mother',true,false,'public','{"name":"Jöns/Jonas Andersson Polin","alt":"Polijn / Paulin","role":"Helena Jönsdotters far","born":"ca 1682","died":"1758-05-24","status":"confirmed","place":"Varberg / Träslöv, Klockaregården och Lars Trulsgård","facts":[["Yrke","Klockare"],["Begravd","1758-06-04"],["Dödsorsak","Ålderdomskrämpor"],["Gravplats","Troligen vid Träslövs kyrkas västra kyrkogavel, nära stora porten och på norra sidan. Läsningen är medel-hög som gravplatsbeskrivning men medel för exakt ordalydelse."],["Klockaretjänst","Kom till tjänsten 1703; lämnade efter 1747 till mågen Bengt Ehn"],["Vigsel","1705-03-19 med Kari/Karin Helgesdotter"],["Skultagårdsspår","Sannolikt fadder/vittne vid Skultagården 1704-07-10, året före vigseln"],["Kyrkoboksspår","Signaturen J. A. Polin vid slutet av 1707 års kyrkoboksanteckningar är ett mycket starkt indicium på hans skrivande/kyrkliga roll"],["Barnspår","Beata 1707, Helena 1713, Petter 1721, Kerstin/Kirsti 1725 och Anna 1728 förs som starka eller sannolika Polin-barn med olika källstatus"],["Polin-nätverk","Lars Polin förekommer sannolikt som fadder 1707 och har ett separat vigselindex i Varberg med Maria Jöransdotter; relationen till Jöns är ännu okänd"],["Far","Anders Jönsson Polin enligt Leif Lundquist"],["Mor","Ingrid enligt Leif Lundquist"],["Källstatus","Vigsel, Helenas födelsenotis och Jöns dödsnotis originalkontrollerade; fadder- och syskonspår från v102 är delvis starka men ska fortsatt omläsas"]],"story":["Jöns eller Jonas Andersson Polin var klockare i Träslöv och kom enligt dödsnotisen till klockaretjänsten 1703. Dödsnotisen anger att han kom från Varberg, levde måttfullt och gudfruktigt samt lämnade tjänsten efter 1747 till sin måg Bengt Ehn.","V102-materialet gör honom mer levande: han förekommer sannolikt som fadder vid Skultagården redan 1704, året före vigseln med Karin Helgesdotter. Det bevisar inte hemvist där, men visar troligen ett tidigt socialt band till Karins familjemiljö.","I kyrkoboken för 1707 finns en stark signatur/årsslutsnotering som läses J. A. Polin. Den passar Jöns Andersson Polin och antyder att han själv kan ha varit inblandad i förandet eller sammanställningen av kyrkoboken.","Specialavsnittet för Klockaregården/Prästgården ger starka Polin-familjehändelser: Beata 1707, Helena 1713 och Petter 1721. Senare poster för Kerstin/Kirsti 1725 och Anna 1728 hör också till familjens sidospår.","Slutraderna i dödsnotisen bedöms sannolikt beskriva gravplatsen: vid västra kyrkogaveln, nära stora porten, på norra sidan. Uppgiften är viktig för lokalhistorien men ska hållas försiktigt tills ordalydelsen är helt säker."],"timeline":[["ca 1682","Föds eller kommer från Varberg enligt dödsnotisen."],["1703","Kommer till klockaretjänsten i Träslöv."],["1704-07-10","Förekommer sannolikt som fadder/vittne i Skultagårdens material."],["1705-03-19","Vigs med Kari/Karin Helgesdotter."],["1707-04-15/17","Dottern Beata föds/döps enligt mycket stark Polin-post i Klockaregården/Prästgården-avsnittet."],["1707","J. A. Polin-signaturen avslutar sannolikt årets kyrkoboksanteckningar."],["1713-10-06/07","Dottern Helena föds."],["1721-10-31/11-05","Sonen Petter föds och döps enligt stark Polin-post."],["1725-08-12/15","Dottern Kerstin/Kirsti föds och döps enligt sannolik Polin-post; möjlig Mårten Andersson som fadder är obekräftad."],["1728-01-21/26","Dottern Anna föds och döps enligt Polin-familjepost."],["efter 1747","Lämnar klockaretjänsten till mågen Bengt Ehn."],["1758-05-24","Dör av ålderdomskrämpor."],["1758-06-04","Begravs. Gravplatsen tolkas sannolikt som vid västra kyrkogaveln, nära stora porten, på norra sidan."]],"parents":["anders_jonsson_polin","ingrid_polin"],"children":["beata_jonsdotter_polin","helena_jonsdotter_1713","petter_jonsson_polin","kerstin_jonsdotter_polin_1725","anna_jonsdotter_polin_1728"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karin_helgesdotter_1685','kari-karin-helgesdotter','Kari/Karin Helgesdotter','Kari Heljesdotter','mother',true,false,'public','{"name":"Kari/Karin Helgesdotter","alt":"Kari Heljesdotter","role":"Helena Jönsdotters mor","born":"ca 1685","died":"1773-01-10","status":"likely","place":"Niels Olufs Hemman / Nils Olsgård, senare Skultagårdsmiljön","facts":[["Barndomsmiljö","N:o 26 Niels Olufs Hemman i Träslöf, senare tolkat som Nils Olsgård"],["Hushållsfynd","En dotter Karin Helgesdotter, omkring 4 år, finns med hög sannolikhet i Helge Svenssons och Kerstin Olsdotters hushåll"],["Vigsel","1705-03-19 med Jöns/Jonas Andersson Polin"],["Far","Helge Svensson enligt Leif Lundquist och stärkt genom hushållsfyndet"],["Mor","Kerstin Olsdotter enligt Leif Lundquist och stärkt genom hushållsfyndet"],["Dotter","Helena Jönsdotter, född mellan 6 och 7 oktober 1713"],["Källstatus","Vigsel originalkontrollerad; hushållet på Nils Olsgård är ett mycket starkt originalfynd men personkopplingen hålls fortsatt källkritiskt"]],"story":["Kari eller Karin Helgesdotter vigdes 19 mars 1705 med Jöns/Jonas Andersson Polin. Namnformen Kari Heljesdotter bör bevaras som original-/indexform.","V102-materialet stärker hennes bakgrund betydligt. På N:o 26 Niels Olufs Hemman i Träslöf, identifierat som Nils Olsgård, finns ett hushåll med Helge Svensson, Kerstin Olsdotter och flera barn. Den sista barnraden läses mycket starkt som Karin Helgesdotter, omkring fyra år.","Det gör Nils Olsgård till en mycket sannolik barndomsmiljö för Karin, medan Skultagården snarare verkar bli tydlig senare genom Helge Svensson och dottern Helenas hemvist vid vigseln 1731.","Uppgiften om död 1773-01-10 kommer fortsatt från Leif Lundquist och behöver egen originalkontroll."],"timeline":[["ca 1685-1686","Föds sannolikt omkring denna tid utifrån åldersuppgiften på Nils Olsgård."],["ca 1690","Förekommer sannolikt som barn i Helge Svenssons hushåll på N:o 26 Niels Olufs Hemman / Nils Olsgård."],["1705-03-19","Vigs med Jöns/Jonas Andersson Polin."],["1713-10-06/07","Dottern Helena föds."],["1773-01-10","Död enligt Leif Lundquist."]],"parents":["helge_svensson","kerstin_olsdotter"],"children":["beata_jonsdotter_polin","helena_jonsdotter_1713","petter_jonsson_polin","kerstin_jonsdotter_polin_1725","anna_jonsdotter_polin_1728"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('beata_jonsdotter_polin','beata-jonsdotter-polin','Beata Jönsdotter Polin',null,'mother',false,false,'public','{"name":"Beata Jönsdotter Polin","role":"Syskon till Helena Jönsdotter","born":"1707-04-15","status":"likely","place":"Klockaregården, Träslöv","facts":[["Döpt","1707-04-17"],["Far","Jöns/Jonas Andersson Polin, mycket stark kandidat"],["Mor","Karin Helgesdotter, familjekoppling stark men moderns namn ska läsas i originalposten"],["Faddrar","Sannolikt Lars Polin och Sara Larsdotter samt flera ännu osäkra faddrar"],["Källstatus","Mycket stark Polin-post i v102; tidigare bedömning att Beata 1707 saknades i original är överspelad"]],"story":["Beata är ett viktigt sidospår i Polin-familjen. En tydligare närbild i v102 visar en post från april 1707 där barnet Beata uttryckligen kan läsas och familjenamnet med hög sannolikhet är Polin.","Fadderläsningen Lars Polin är särskilt intressant, eftersom den kan peka mot en nära släkting eller åtminstone ett tätt socialt nätverk runt Jöns Andersson Polin."],"timeline":[["1707-04-15","Föds enligt mycket stark Polin-post."],["1707-04-17","Döps."],["1781","Dödsår enligt sekundärmaterial; behöver separat kontroll."]],"parents":["jons_polin_1682","karin_helgesdotter_1685"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('petter_jonsson_polin','petter-jonsson-polin','Petter Jönsson Polin',null,'mother',false,false,'public','{"name":"Petter Jönsson Polin","role":"Syskon till Helena Jönsdotter","born":"1721-10-31","status":"likely","place":"Klockaregården, Träslöv","facts":[["Döpt","1721-11-05"],["Far","Jöns/Jonas Andersson Polin, stark kandidat"],["Faddrar","Bland annat Anders Nilsson med anknytning till Klastorp, Olof i Lunden och möjlig Greta Bolin/Polin; flera läsningar ska kontrolleras"],["Källstatus","Stark Polin-familjepost i v102, stödd av sekundärmaterial som placerar Petter vid Klockaregården"]],"story":["Petter hör till Polin-familjens sidolinje. V102 beskriver posten 1721 som en stark kandidat för Petter Jönsson Polins födelse- och dopnotis.","Fadderlistan är genealogiskt värdefull eftersom den åter för in Lunden, Klastorp och möjliga Polin/Bolin-personer i familjens närhet."],"timeline":[["1721-10-31","Föds enligt stark Polin-familjepost."],["1721-11-05","Döps."],["1784","Dödsår enligt sekundärmaterial; behöver separat kontroll."]],"parents":["jons_polin_1682","karin_helgesdotter_1685"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('kerstin_jonsdotter_polin_1725','kerstin-kirsti-jonsdotter-polin','Kerstin/Kirsti Jönsdotter Polin',null,'mother',false,false,'public','{"name":"Kerstin/Kirsti Jönsdotter Polin","role":"Syskon till Helena Jönsdotter","born":"1725-08-12","status":"working","place":"Klockaregården, Träslöv","facts":[["Döpt","1725-08-15"],["Far","Sannolikt Jöns/Jonas Andersson Polin"],["Möjlig fadder","Mårten Andersson kan förekomma i fadderlistan, men läsningen är ännu obekräftad"],["Källstatus","Sannolik Polin-post i v102; prioriterad omläsning behövs"]],"story":["Kerstin eller Kirsti förs som ett försiktigt sidospår i Polin-familjen. Posten från augusti 1725 verkar ange en dotter med detta namn.","Den möjliga fadderläsningen Mårten Andersson är extra viktig. Om den bekräftas visar den att Mårten fanns i Polin-familjens krets redan sex år före vigseln med Helena Jönsdotter, men just nu ska fyndet hållas öppet."],"timeline":[["1725-08-12","Föds enligt sannolik Polin-post."],["1725-08-15","Döps."],["1725","Möjlig Mårten Andersson i fadderlistan; ej bekräftat."]],"parents":["jons_polin_1682","karin_helgesdotter_1685"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_jonsdotter_polin_1728','anna-jonsdotter-polin','Anna Jönsdotter Polin',null,'mother',false,false,'public','{"name":"Anna Jönsdotter Polin","role":"Syskon till Helena Jönsdotter","born":"1728-01-21","status":"working","place":"Klockaregården, Träslöv","facts":[["Döpt","1728-01-26"],["Far","Sannolikt Jöns/Jonas Andersson Polin"],["Källstatus","Polin-familjepost i v102; fadderlistan är ännu inte fullständigt normaliserad"]],"story":["Anna är ett sidospår i Polin-familjen och visar att familjen fortfarande är aktiv i den kyrkliga/klockareanknutna miljön i slutet av 1720-talet.","Fadderlistan är lång men ännu för osäker för att normaliseras fullt ut i trädet."],"timeline":[["1728-01-21","Föds enligt Polin-familjepost."],["1728-01-26","Döps."]],"parents":["jons_polin_1682","karin_helgesdotter_1685"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('lars_polin','lars-polin','Lars Polin',null,'shared',false,false,'public','{"name":"Lars Polin","role":"Möjlig släkting i Polin-nätverket","status":"working","place":"Varberg / Träslöv","facts":[["Möjlig roll","Sannolik fadder vid Beata Jönsdotter Polins dop 1707"],["Vigselindex","Lars Polin och Maria Jöransdotter/Joransdotter i Varberg, brett daterat 1700-1750 i index"],["Relation till Jöns","Okänd; möjlig nära släkting eller nära social kontakt"],["Källstatus","Starkt index- och fadderspår, men originalvigsel och släktskap återstår"]],"story":["Lars Polin är ännu inte införd som släkting i direkt mening, men v102 gör honom viktig för Polin-nätverket. Han förekommer sannolikt som fadder vid Beatas dop 1707.","Ett separat vigselindex placerar en Lars Polin med Maria Jöransdotter i Varberg. Tills originalposten är kontrollerad ska relationen till Jöns Andersson Polin hållas öppen."],"timeline":[["1707-04-17","Sannolik fadder vid Beata Jönsdotter Polins dop."],["1700-1750","Vigselindex i Varberg med Maria Jöransdotter; exakt datum saknas i öppet index."]],"parents":[],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anders_jonsson_polin','anders-jonsson-polin','Anders Jönsson Polin',null,'mother',true,false,'public','{"name":"Anders Jönsson Polin","role":"Jöns Polins far","status":"likely","facts":[["Yrke","Sadelmakare"],["Hustru","Ingrid"],["Son","Jöns/Jonas Andersson Polin"],["Källstatus","Leif Lundquist"]],"story":["Anders Jönsson Polin förs in som far till Jöns/Jonas Andersson Polin enligt Leif Lundquists Halländsk antavla 4. Uppgiften är en accepterad arbetsgenealogi och ska originalkontrolleras när källor hittas."],"parents":[],"children":["jons_polin_1682"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('ingrid_polin','ingrid','Ingrid',null,'mother',true,false,'public','{"name":"Ingrid","role":"Jöns Polins mor","born":"1646","died":"1747","status":"likely","facts":[["Make","Anders Jönsson Polin"],["Son","Jöns/Jonas Andersson Polin"],["Källstatus","Leif Lundquist"],["Notering","Patronymikonet Andersdotter ska inte låsas utan ytterligare källa"]],"story":["Ingrid förs in som mor till Jöns/Jonas Andersson Polin enligt Leif Lundquist. Ett Ancestry-träd anger Inger Andersdotter, men patronymikonet lämnas öppet tills en bättre källa finns."],"parents":[],"children":["jons_polin_1682"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('helge_svensson','helge-svensson','Helge Svensson',null,'mother',true,false,'public','{"name":"Helge Svensson","role":"Karin Helgesdotters far","born":"ca 1650","died":"före 1731-04-16","status":"likely","place":"Niels Olufs Hemman / Nils Olsgård, senare Skultagården","facts":[["Hustru","Kerstin Olsdotter"],["Barn i hushåll","Olof, Simon, Inger, sannolikt Margareta, Anders och Karin Helgesdotter enligt N:o 26-hushållet"],["Hushållsfynd","På N:o 26 Niels Olufs Hemman läses Helge Svensson omkring 40 år med hustru och barn; detta är ett mycket viktigt originalspår"],["Begravd","1731-04-16 enligt v102-materialets samlade bedömning"],["Ålder vid begravning","omkring 80 år"],["Äldre uppgift","1731-04-02 från Leif Lundquist ska inte längre användas som exakt originalbekräftat dödsdatum utan kontroll"],["Källstatus","Föräldrakopplingen bygger på Leif Lundquist och stärks kraftigt av hushållet på Nils Olsgård; begravningsuppgiften behöver hållas källkritiskt"]],"story":["Helge Svensson förs in som far till Karin Helgesdotter enligt Leif Lundquist, men v102 ger ett mycket starkare gårds- och hushållsspår. På N:o 26 Niels Olufs Hemman i Träslöv finns ett hushåll som med hög sannolikhet innehåller Helge, hustrun Kerstin Olsdotter och flera barn, däribland Karin.","Åldersuppgifterna passar den övriga källbilden: Helge anges omkring 40 år i hushållet och omkring 80 år vid begravningen 1731, vilket pekar mot födelse omkring 1650-1651.","Arbetsbilden är nu att Helge och familjen först hör till Nils Olsgård/Niels Olufs Hemman, medan kopplingen till Skultagården blir tydligare senare. Det viktiga framåt är att hitta exakt när och varför familjen flyttar eller knyts dit."],"timeline":[["ca 1650","Föds ungefärligen utifrån åldersuppgifter."],["ca 1690","Återfinns sannolikt med hustru och barn på N:o 26 Niels Olufs Hemman / Nils Olsgård."],["1705","Dottern Karin gifter sig med Jöns/Jonas Andersson Polin."],["1731-04-16","Begravs enligt v102-materialets samlade bedömning; äldre datum 1731-04-02 hålls som sekundärt/ej exakt säkrat."]],"parents":[],"children":["karin_helgesdotter_1685"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('kerstin_olsdotter','kerstin-kiersten-olsdotter','Kerstin/Kiersten Olsdotter',null,'mother',true,false,'public','{"name":"Kerstin/Kiersten Olsdotter","role":"Karin Helgesdotters mor","born":"ca 1642","died":"före 1729-12-21","status":"likely","place":"Träslöv / Niels Olufs Hemman","facts":[["Make","Helge Svensson"],["Dotter","Karin Helgesdotter"],["Hushållsfynd","Kerstin/Kirstin Olsdotter, omkring 46 år, finns sannolikt i Helge Svenssons hushåll på N:o 26 Niels Olufs Hemman"],["Begravd","1729-12-21 i Träslöv"],["Ålder vid begravning","omkring 87 år"],["Källkritisk rättelse","Ancestry-uppgiften om april 1731 ska betraktas som felaktig eller sammanblandad"],["Gårdsangivelse","Begravningsnotisen bekräftar henne som Helge Svenssons hustru men ger ingen säker Skultagård-angivelse"],["Källstatus","Begravningen är originalbekräftad i v102; föräldrakopplingen till Karin stärks av hushållsfyndet men hålls fortsatt källkritiskt"]],"story":["Kerstin eller Kiersten Olsdotter förs in som mor till Karin Helgesdotter enligt Leif Lundquist, och v102 stärker henne genom två viktiga spår.","För det första finns hon sannolikt i hushållet på N:o 26 Niels Olufs Hemman tillsammans med Helge Svensson och barnen. För det andra har hennes begravningsnotis i Träslöv identifierats: hon begravs 21 december 1729 som Helge Svenssons hustru, omkring 87 år gammal.","Detta ersätter den tidigare Ancestry-uppgiften om april 1731. Däremot bevisar just begravningsnotisen inte att hon bodde på Skultagården vid döden."],"timeline":[["ca 1642","Beräknat födelseår utifrån åldern vid begravningen."],["ca 1690","Återfinns sannolikt i hushållet på N:o 26 Niels Olufs Hemman / Nils Olsgård."],["1729-12-21","Begravs i Träslöv, omkring 87 år gammal."]],"parents":[],"children":["karin_helgesdotter_1685"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('olof_nilsson_1750','olof-nilsson','Olof Nilsson',null,'mother',true,false,'public','{"name":"Olof Nilsson","role":"Morfars farfars farfars far","born":"1750-09-26","status":"confirmed","place":"Olof Svensgård, Träslöv","facts":[["Döpt","1750-09-29"],["Far","Nils Wångersson"],["Mor","Karin Gunnesdotter"],["Vigsel","1775-02-05 med änkan Karin Svensdotter"],["Källstatus","Födelse- och dopnotis godtas som rätt Olof Nilsson"]],"story":["Olof Nilsson föds 26 september 1750 i Träslöv och döps 29 september. Födelsenotisen anger föräldrarna Nils Wångersson och Karin Gunnesdotter.","Han vigs 5 februari 1775 med änkan Karin Svensdotter. Paret återfinns senare vid Olof Svensgård och får bland annat sonen Bengt Olofsson, född 1784.","Två yngre Olof-poster i Klastorps by har kontrollerats och avförts som kandidater till Bengt Olofssons far."],"timeline":[["1750-09-26","Föds i Träslöv."],["1775-02-05","Vigs med änkan Karin Svensdotter."],["1784-08-10","Sonen Bengt föds vid Olof Svensgård."]],"parents":["nils_wangersson","karin_gunnesdotter"],"children":["olena_olofsdotter_1775","borta_olofsdotter_1777","nils_olofsson_1780","bengt_olofsson_1784"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karin_svensdotter_1741','karin-svensdotter','Karin Svensdotter','Karin Swensdotter','mother',true,false,'public','{"name":"Karin Svensdotter","alt":"Karin Swensdotter","role":"Morfars farfars farfars mor","born":"1741-05-19","died":"1821-05-22","status":"confirmed","place":"Olof Svensgård / Träslöv","facts":[["Begravd","1821-05-27"],["Dödsorsak","Ålderdom"],["Ålder vid död","80 år"],["Första make","Olof Bengtsson"],["Andra make","Olof Nilsson"],["Dödsplats/bostadsangivelse","Börge Bengtssons gård i Träslöv"],["Källstatus","Dödsnotis, husförhör och barnindex stärker identiteten; födelsenotis återstår"]],"story":["Karin Svensdotter föds enligt senare husförhör 19 maj 1741. Datumet passar mycket väl med åldersuppgifterna i sonen Bengts födelsenotis 1784 och hennes dödsnotis 1821.","Hon var först gift med Olof Bengtsson och fick minst fyra barn 1762-1772. Vid vigseln med Olof Nilsson 1775 kallas hon änka.","Med Olof Nilsson får hon bland annat Bengt Olofsson, född 1784 vid Olof Svensgård. Hennes dödsnotis 1821 anger bostad i Börge Bengtssons gård i Träslöv, men det är en bostadsangivelse och inte bevis på ytterligare äktenskap."],"timeline":[["1741-05-19","Födelsedatum enligt senare husförhör."],["1762-08-11","Första kända barnet med Olof Bengtsson föds."],["1775-02-05","Vigs som änka med Olof Nilsson."],["1784-08-10","Sonen Bengt föds vid Olof Svensgård."],["1821-05-22","Dör i Träslöv, dödsorsak ålderdom."],["1821-05-27","Begravs."]],"parents":[],"children":["bengt_olofsson_1762","sven_olofsson_1765","borje_olofsson_1769","bengt_olofsson_1772","olena_olofsdotter_1775","borta_olofsdotter_1777","nils_olofsson_1780","bengt_olofsson_1784"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_wangersson','nils-wangersson','Nils Wångersson',null,'shared',false,false,'public','{"name":"Nils Wångersson","role":"Olof Nilssons far","status":"confirmed","place":"Träslöv","facts":[["Barn","Olof Nilsson, född 1750-09-26"],["Källstatus","Bekräftad som far i Olofs födelsenotis"]],"story":["Nils Wångersson är bekräftad som far till Olof Nilsson i födelse- och dopnotisen 1750.","Hans egna födelse-, vigsel- och dödsuppgifter återstår att identifiera."],"parents":[],"children":["olof_nilsson_1750"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karin_gunnesdotter','karin-gunnesdotter','Karin Gunnesdotter',null,'shared',false,false,'public','{"name":"Karin Gunnesdotter","role":"Olof Nilssons mor","status":"confirmed","place":"Träslöv","facts":[["Barn","Olof Nilsson, född 1750-09-26"],["Källstatus","Bekräftad som mor i Olofs födelsenotis"]],"story":["Karin Gunnesdotter är bekräftad som mor till Olof Nilsson i födelse- och dopnotisen 1750. Ancestry-trädet visar också Karin Gunnesdotter som mor, vilket stödjer läsningen.","Hennes egna födelse-, vigsel- och dödsuppgifter återstår att identifiera."],"parents":[],"children":["olof_nilsson_1750"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('olof_bengtsson_forsta','olof-bengtsson','Olof Bengtsson',null,'shared',false,false,'public','{"name":"Olof Bengtsson","role":"Karin Svensdotters första make","status":"working","place":"Olof Svensgård / Träslöv","facts":[["Make till","Karin Svensdotter före 1775"],["Död","Före 1775-02-05, eftersom Karin kallas änka vid vigseln med Olof Nilsson"],["Barn","Bengt, Sven, Börje och Bengt"]],"story":["Olof Bengtsson är identifierad som Karin Svensdotters första make genom barnens födelseindex och Karins senare vigsel som änka 1775.","Exakta uppgifter om hans födelse, vigsel med Karin och död före 1775 återstår att hitta."],"parents":[],"children":["bengt_olofsson_1762","sven_olofsson_1765","borje_olofsson_1769","bengt_olofsson_1772"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_olofsson_1762','bengt-olofsson-1762-08-11','Bengt Olofsson',null,'shared',false,false,'public','{"name":"Bengt Olofsson","role":"Barn i Karins första äktenskap","born":"1762-08-11","status":"working","place":"Olof Svensgård, Träslöv","facts":[["Föräldrar","Olof Bengtsson och Karin Svensdotter"],["Kommentar","Sannolikt avliden före yngre brodern Bengt född 1772"]],"story":["Bengt föds 11 augusti 1762 enligt födelseindex, som barn till Olof Bengtsson och Karin Svensdotter. Eftersom en yngre son också får namnet Bengt 1772 är det sannolikt att den äldre Bengt avled ung."],"parents":["olof_bengtsson_forsta","karin_svensdotter_1741"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
