insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_olofsson_1772','bengt-olofsson-1772-11-27','Bengt Olofsson',null,'shared',false,false,'public','{"name":"Bengt Olofsson","role":"Barn i Karins första äktenskap","born":"1772-11-27","status":"working","place":"Träslöv","story":["Bengt förs som barn till Olof Bengtsson och Karin Svensdotter enligt födelseindex. Han är sannolikt namngiven efter en äldre bror Bengt som avlidit före 1772."],"parents":["olof_bengtsson_forsta","karin_svensdotter_1741"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
