insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('ingemar_bengtsson','ingemar-bengtsson','Ingemar Bengtsson',null,'mother',false,false,'public','{"name":"Ingemar Bengtsson","status":"confirmed","role":"Barn","story":["Son till Karin och Harry. Grenen är ännu inte utforskad."],"parents":["karin_margit","harry_bengtsson"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('gerd_bengtsson','gerd-bengtsson','Gerd Bengtsson',null,'shared',true,true,'family','{"name":"Gerd Bengtsson","born":"1958-08-06","status":"confirmed","role":"Barn","facts":[["Make","Göran Nilsson"],["Barn","Axel och Ebba"]],"story":["Gerd föds 6 augusti 1958, dotter till Karin och Harry.","Gerd gifter sig med Göran Nilsson. Tillsammans får de två barn: Axel och Ebba."],"parents":["karin_margit","harry_bengtsson"],"children":["axel_nilsson","ebba_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('goran_nilsson','goran-nilsson','Göran Nilsson',null,'shared',true,true,'family','{"name":"Göran Nilsson","role":"Far","born":"1956-05-26","status":"confirmed","facts":[["Maka","Gerd Bengtsson"],["Barn","Axel och Ebba"],["Mor","Elsa Helena"],["Far","Nils Stig Henning Nilsson"]],"story":["Göran Nilsson föds 26 maj 1956. Han är gift med Gerd Bengtsson och tillsammans får de barnen Axel och Ebba.","På pappas sida är hans mor Elsa Helena, född 24 september 1920 i Torpa, och hans far Nils Stig Henning Nilsson, född 13 maj 1924."],"parents":["elsa_helena_karlsson","nils_stig_henning_nilsson"],"children":["axel_nilsson","ebba_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_stig_henning_nilsson','nils-stig-henning-nilsson','Nils Stig Henning Nilsson',null,'father',true,true,'family','{"name":"Nils Stig Henning Nilsson","role":"Farfar","born":"1924-05-13","status":"working","place":"Årstad / farfars sida","facts":[["Föräldrar","Nils Birger Gustafsson och Alma Sofia Nilsson"],["Syskon","Ingrid Linnéa, Karl Rune Ingvar, Sonja Gunnel, Sven Erik Gustaf, Lars Olof Bertil och Nils Ove Sjunne"],["Källstatus","Namn, födelsedatum och hushållsrelationer belagda i hushållsöversikt/index; födelsenotis behöver kontrolleras"],["Kommentar","Tidigare preliminär avläsning 1931-05-19 ersätts av 1924-05-13"]],"story":["Nils Stig Henning Nilsson är Göran Nilssons far och därmed Axels farfar.","Han förs med födelsedatum 13 maj 1924 enligt den senaste hushållsöversikten. Samma person förekommer två gånger i materialet med samma födelsedatum, vilket behandlas som en indexdubblett och inte som två personer.","Hans föräldrar är Nils Birger Gustafsson och Alma Sofia, född Nilsson. Födelsenotis/originalkälla ska kontrolleras för att låsa födelseförsamling och dopuppgift."],"parents":["nils_birger_gustafsson","alma_sofia_nilsson"],"children":["goran_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_birger_gustafsson','nils-birger-gustafsson','Nils Birger Gustafsson',null,'father',true,false,'public','{"name":"Nils Birger Gustafsson","role":"Farfars far","born":"1896-07-03","status":"confirmed","place":"Fjellalunda / Årstad","facts":[["Döpt","1896-07-05"],["Födelseförsamling","Årstad (N)"],["Vigsel","1924-02-16 i Årstad med Alma Sofia Nilsson"],["Bostadsorter","Fjellalunda; Årstad; Sannarps Torp/Årstad 24:1; Stockarne; Bengtstorp; Smedjegård/Hästhagen/Slättaled"],["Föräldrar","Gustaf Henning Johansson och Augusta Olivia Larsdotter"],["Källstatus","Födelse, dop och föräldrar originalkällbekräftade; boendehistorik registerbekräftad"]],"story":["Nils Birger Gustafsson föds 3 juli 1896 i Årstad och döps 5 juli. Födelsenotisen anger föräldrarna Gustaf Henning Johansson och Augusta Olivia Larsdotter i Fjellalunda.","Han vigs 16 februari 1924 i Årstad med Alma Sofia Nilsson. Paret får barnen Nils Stig Henning, Ingrid Linnéa, Karl Rune Ingvar, Sonja Gunnel, Sven Erik Gustaf, Lars Olof Bertil och Nils Ove Sjunne.","ArkivDigital-posterna visar honom i Årstad över flera perioder, bland annat Fjellalunda, Sannarps Torp/Stockarne, Bengtstorp och Smedjegård/Hästhagen/Slättaled. Rörelsemönstret är registerbekräftat och kan senare fördjupas i originalbilder."],"timeline":[["1896-07-03","Föds i Årstad, kopplad till Fjellalunda."],["1896-07-05","Döps."],["1905-1920","Finns i hushållet i Fjellalunda."],["1924-02-16","Vigs med Alma Sofia Nilsson i Årstad."],["1930-1948","Förekommer i flera Årstad-poster, bland annat Sannarps Torp/Stockarne och Bengtstorp."]],"parents":["gustaf_henning_johansson","augusta_olivia_larsdotter"],"children":["nils_stig_henning_nilsson","ingrid_linnea_nilsson","karl_rune_ingvar_nilsson","sonja_gunnel_nilsson","sven_erik_gustaf_nilsson","lars_olof_bertil_nilsson","nils_ove_sjunne_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('alma_sofia_nilsson','alma-sofia-nilsson','Alma Sofia Nilsson',null,'father',true,false,'public','{"name":"Alma Sofia Nilsson","role":"Farfars mor","born":"1900-04-04","status":"confirmed","place":"Åryd / Bräkne-Hoby / Landskrona / Ränneslöv / Årstad","facts":[["Döpt","1900-04-06 i Åryd"],["Föräldrar","Nils Månsson och Johanna Johansdotter/Johansdr"],["Vigsel","1924-02-16 i Årstad med Nils Birger Gustafsson"],["Yrken före vigsel","Tjänarinna i Landskrona/Norra Fäladsmarken och Karlshamn/Uppsala; mejerielev i Landskrona/Tärnan"],["Rörelsekedja 1916-1918","Bräkne-Hoby/Efvaryd -> Landskrona/Sten Sture -> Landskrona/Norra Fäladsmarken -> Karlshamn/Uppsala -> Bräkne-Hoby/Efvaryd"],["Rörelsekedja 1922-1924","Årstad -> Landskrona/Tärnan -> Ränneslöv/Vallberga -> Årstad"],["Barn","Nils Stig Henning, Ingrid Linnéa, Karl Rune Ingvar, Sonja Gunnel, Sven Erik Gustaf, Lars Olof Bertil och Nils Ove Sjunne"],["Källstatus","Födelsenotis, familjepost i Efvaryd, Landskrona-poster, Karlshamn-post, Ränneslöv-post och Årstad sida 393 inlagda i senaste farfarsfilen"]],"story":["Alma Sofia Nilsson föds 4 april 1900 i Åryd och döps 6 april. Födelsenotisen anger föräldrarna Nils Månsson och Johanna Johansdotter/Johansdr.","V61 fördjupar hennes liv före äktenskapet. Familjeposten i Bräkne-Hoby/Efvaryd visar att hon lämnar familjehemmet för Landskrona 1916. Där finns hon först i Sten Sture N:o 3 och därefter i Norra Fäladsmarken som tjänarinna, innan hon flyttar till Karlshamn/Uppsala 1918 och åter till Bräkne-Hoby samma år.","Senare finns en ny kedja där Alma kommer från Årstad till Landskrona/Tärnan år 1922. I Tärnan N:o 16 står hon som mejerielev och flyttar vidare till Ränneslöv/Vallberga 1923. Därifrån går hon till Årstad 24 januari 1924 och förs efter vigseln 16 februari 1924 in i Nils Birger Gustafssons hushåll."],"timeline":[["1900-04-04","Föds i Åryd."],["1900-04-06","Döps i Åryd."],["1916-12-15","Flyttar från Bräkne-Hoby/Efvaryd till Landskrona/Sten Sture."],["1917-11-15","Finns i Landskrona/Norra Fäladsmarken som tjänarinna efter hänvisning från Sten Sture."],["1918-07-10","Flyttar från Landskrona till Karlshamn/Uppsala."],["1918-10-21","Flyttar från Karlshamn tillbaka till Bräkne-Hoby/Efvaryd."],["1922","Kommer från Årstad till Landskrona/Tärnan N:o 16, där hon står som mejerielev."],["1923","Flyttar från Landskrona/Tärnan till Ränneslöv/Vallberga; datumet är svårläst, möjligen 9 eller 23 april."],["1924-01-24","Flyttar från Ränneslöv till Årstad."],["1924-02-16","Vigs med Nils Birger Gustafsson i Årstad."],["1924-09-01","Sonen Nils Stig Henning föds i Årstad."]],"parents":["nils_mansson_aryd","johanna_johansdotter_aryd"],"children":["nils_stig_henning_nilsson","ingrid_linnea_nilsson","karl_rune_ingvar_nilsson","sonja_gunnel_nilsson","sven_erik_gustaf_nilsson","lars_olof_bertil_nilsson","nils_ove_sjunne_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_mansson_aryd','nils-mansson','Nils Månsson',null,'father',true,false,'public','{"name":"Nils Månsson","role":"Alma Sofias far","born":"1860-06-18","status":"confirmed","place":"Åryd / Byga eller Bygd / Bräkne-Hoby Efvaryd","facts":[["Födelseförsamling","Åryd enligt hushåll/renskrivning"],["Yrke/titel","Hemmansägare/hemmansbrukare; tidigare även sjöman/fästman i Åryd sida 185"],["Maka","Johanna Johansdotter/Johansdr"],["Barn i hushåll","Thekla Emilia, Sven August, Anna Mathilda, Edla Eleonora, Ernst Frithiof och Alma Sofia"],["Familjepost","Bräkne-Hoby/Efvaryd N:o 7, sida 87"],["Källstatus","Hushållet i Åryd och familjeposten i Efvaryd identifierade; födelsenotis och vigsel ska följas upp"]],"story":["Nils Månsson anges i Alma Sofias födelsenotis och i Åryd-hushållet som hennes far.","Hushållet visar Nils tillsammans med Johanna Johansdotter/Johansdr och barnen Thekla Emilia, Sven August, Anna Mathilda, Edla Eleonora, Ernst Frithiof och Alma Sofia. Födelsedatumet korrigeras i senaste materialet till 18 juni 1860.","Åryd sida 185 visar Nils som sannolik fästman i samband med Johanna och Thekla Emilia. V61 lägger dessutom in familjeposten i Bräkne-Hoby/Efvaryd N:o 7, där Alma senare flyttar ut till Landskrona."],"parents":[],"children":["thekla_emilia_johannasdotter","sven_august_nilsson_aryd","anna_mathilda_nilsson_aryd","edla_eleonora_nilsson_aryd","ernst_frithiof_nilsson_aryd","alma_sofia_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johanna_johansdotter_aryd','johanna-johansdotter','Johanna Johansdotter','Johansdr','father',true,false,'public','{"name":"Johanna Johansdotter","alt":"Johansdr","role":"Alma Sofias mor","born":"1868-06-02","status":"confirmed","place":"Åryd / Gustavsborg","facts":[["Födelseförsamling","Åryd enligt hushåll/renskrivning"],["Make","Nils Månsson"],["Dotter före äktenskap","Thekla Emilia, född 1888-09-05, oäkta i födelsenotisen"],["Barn i hushåll","Thekla Emilia, Sven August, Anna Mathilda, Edla Eleonora, Ernst Frithiof och Alma Sofia"],["Källstatus","Bekräftad som Alma Sofias mor; egen födelsenotis och vigsel återstår att följa upp"]],"story":["Johanna Johansdotter, även skriven Johansdr, är Alma Sofia Nilssons mor enligt födelsenotisen i Åryd 1900.","Thekla Emilias födelsenotis 1888 anger modern som pigan Johanna Johansdotter och saknar angiven far. Senare hushållspost visar Thekla tillsammans med Nils och Johanna med notering om makarna före äktenskapet, men faderskapet ska fortsatt beskrivas försiktigt.","Johanna och Nils återfinns senare i hushållet med barnen Thekla Emilia, Sven August, Anna Mathilda, Edla Eleonora, Ernst Frithiof och Alma Sofia."],"parents":[],"children":["thekla_emilia_johannasdotter","sven_august_nilsson_aryd","anna_mathilda_nilsson_aryd","edla_eleonora_nilsson_aryd","ernst_frithiof_nilsson_aryd","alma_sofia_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('thekla_emilia_johannasdotter','thekla-emilia','Thekla Emilia',null,'father',false,false,'public','{"name":"Thekla Emilia","role":"Äldre halvsyster/hushållssyster till Alma Sofia","born":"1888-09-05","status":"confirmed","place":"Åryd / Gustavsborg","facts":[["Döpt","1888-09-23"],["Notering i födelsenotis","Oäkta"],["Mor","Pigan Johanna Johansdotter"],["Far","Ej angiven i födelsenotisen"],["Senare hushåll","Står med Nils Månsson och Johanna; notering tyder på barn före äktenskapet"]],"story":["Thekla Emilia föds 5 september 1888 i Åryd och döps 23 september. Födelsenotisen anger henne som oäkta och nämner ingen far.","Hon förs därför som Johannas dotter och som Alma Sofias äldre halvsyster eller hushållssyster tills ytterligare källa bekräftar faderskapet. En senare hushållspost med Nils Månsson och Johanna stärker att hon räknades in i familjen."],"parents":["johanna_johansdotter_aryd"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
