insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('ingeborg_natalia_gustafsdotter','ingeborg-natalia','Ingeborg Natalia',null,'father',false,false,'public','{"name":"Ingeborg Natalia","role":"Syskon till Nils Birger","born":"1904-07-03","status":"confirmed","place":"Årstad","story":["Ingeborg Natalia förekommer som dotter i hushållet med Gustaf Henning Johansson och Augusta Olivia Larsdotter i Fjellalunda och senare på sida 425."],"parents":["gustaf_henning_johansson","augusta_olivia_larsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johannes_andersson_arstad','johannes-arvidsson','Johannes Arvidsson',null,'father',true,false,'public','{"name":"Johannes Arvidsson","role":"Gustaf Hennings far","born":"1834-08-06","died":"1871-10-21","status":"confirmed","place":"Okome / N:o 10 Årstad","facts":[["Alternativ födelseuppgift","1834-08-03 i senare husförhör/dödsålder"],["Döpt","troligen 1834-08-10 i Okome"],["Titel","Torpare"],["Begravd","1871-10-29"],["Dödsorsak","Bröstsjukdom"],["Dödsplats","N:o 10 Årstad"],["Föräldrar","Arvid Ivarsson och Gunnil Andreasdotter"],["Källstatus","Födelse-/barndomsspåret i Okome är starkt och kopplat vidare till Årstad; dödsnotisen låses av Jenny Serafias födelsenotis"]],"story":["Johannes Arvidsson är far till Gustaf Henning Johansson enligt födelsenotisen 1863. Tidigare läsning som Johannes Andersson korrigeras till Johannes Arvidsson.","Okome-spåret är nu huvudspår: Johannes föds 6 augusti 1834 i Okome och förekommer som barn i hushåll med Arvid Ivarsson och Gunnil Andreasdotter. Senare renskrivning binder honom vidare till Årstad med Inger Hansdotter och sonen August Julius.","Johannes dör 21 oktober 1871 som torpare under N:o 10 Årstad och begravs 29 oktober. Jenny Serafias födelsenotis anger fadern som avlidne torparen Johannes Arvidsson under N:o 10 Årstad, vilket låser identiteten mot dödsnotisen."],"timeline":[["1834-08-06","Föds i Okome enligt tidig födelse-/barndomskälla."],["1847-1859","Förekommer i Okome, bland annat Sjette Ödgärdet och Jordsbacka."],["1861-09-20","Sonen August Julius föds i Årstad Lid."],["1863-07-15","Sonen Gustaf Henning föds i Årstad."],["1871-10-21","Dör som torpare under N:o 10 Årstad."],["1871-10-29","Begravs."]],"parents":["arvid_ivarsson","gunnil_andreasdotter"],"children":["august_julius_arvidsson","gustaf_henning_johansson","severin_julius_johansson","emma_josefina_johansdotter","jenny_serafia_johansdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('inger_hansdotter_arstad','inger-hansdotter','Inger Hansdotter',null,'father',true,false,'public','{"name":"Inger Hansdotter","role":"Gustaf Hennings mor","born":"1830-08-31","status":"confirmed","place":"Vinberg / Årstad Tröskaregården","facts":[["Födelseort","Vinberg enligt hushållspost"],["Make","Johannes Arvidsson"],["Civilstånd","Änka i Årstad Tröskaregården-poster"],["Källstatus","Moder i Gustaf Hennings födelsenotis; senare änkeposter och barnens födelsenotiser stärker familjekedjan"]],"story":["Inger Hansdotter anges som mor till Gustaf Henning Johansson i födelsenotisen 1863.","Hon står tillsammans med Johannes Arvidsson och sonen August Julius i Årstad AI:6, och senare som Johannes änka i Årstad Tröskaregården tillsammans med barnen Gustaf Henning, Severin Julius, Emma Josefina och Jenny Serafia.","Hennes födelseort anges som Vinberg. Vigseln med Johannes Arvidsson har ännu inte hittats i de kontrollerade Årstad- och Vinberg-bilderna för 1859-1862."],"parents":[],"children":["august_julius_arvidsson","gustaf_henning_johansson","severin_julius_johansson","emma_josefina_johansdotter","jenny_serafia_johansdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('august_julius_arvidsson','august-julius','August Julius',null,'father',false,false,'public','{"name":"August Julius","role":"Syskon till Gustaf Henning","born":"1861-09-20","status":"confirmed","place":"Årstad Lid","facts":[["Döpt","1861-09-22"],["Föräldrar","Johannes Arvidsson och Inger Hansdotter"],["Källa","Årstads födelse- och dopbok 1861, inzoomad kontroll i senaste farfarsfilen"]],"story":["August Julius föds 20 september 1861 i Årstad Lid och döps 22 september.","Födelsenotisen bekräftar föräldrarna som torparen Johannes Arvidsson och Inger Hansdotter. Han är därmed äldre bror till Gustaf Henning Johansson i farfarslinjen."],"parents":["johannes_andersson_arstad","inger_hansdotter_arstad"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('severin_julius_johansson','severin-julius-johansson','Severin Julius Johansson',null,'father',false,false,'public','{"name":"Severin Julius Johansson","role":"Möjligt syskon till Gustaf Henning","born":"1867-09-16","status":"working","place":"Årstad / Sannarp","facts":[["Källstatus","Sannolik bror i samma hushåll; födelsenotis bör kontrolleras"]],"story":["Severin Julius förekommer i samma hushållsmiljö som Inger Hansdotter och Gustaf Henning Johansson. Han är sannolikt Gustaf Hennings bror, men relationen bör kontrolleras i födelsenotis."],"parents":["johannes_andersson_arstad","inger_hansdotter_arstad"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('emma_josefina_johansdotter','emma-josefina-johansdotter','Emma Josefina Johansdotter',null,'father',false,false,'public','{"name":"Emma Josefina Johansdotter","role":"Möjligt syskon till Gustaf Henning","born":"1869-07-30","status":"working","place":"Årstad Tröskaregården","facts":[["Källstatus","Sannolik syster i samma hushåll; tidigare misstänkt dödsnotering 1874 är inte bekräftad"]],"story":["Emma Josefina förekommer i hushåll med Inger Hansdotter och Gustaf Henning Johansson. Hon är sannolikt syster till Gustaf Henning, men relationen bör kontrolleras vidare.","Tidigare preliminära dödsnoteringar från 1874 ska inte föras som bekräftade, eftersom dödbokskontrollen inte gav säker träff."],"parents":["johannes_andersson_arstad","inger_hansdotter_arstad"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('jenny_serafia_johansdotter','jenny-serafia-johansdotter','Jenny Serafia Johansdotter',null,'father',false,false,'public','{"name":"Jenny Serafia Johansdotter","role":"Syskon till Gustaf Henning","born":"1871-12-15","status":"confirmed","place":"Årstad / N:o 10 Årstad","facts":[["Döpt","1871-12-24"],["Fader","Avlidne torparen Johannes Arvidsson under N:o 10 Årstad"],["Moder","Inger Hansdotter"],["Moderns ålder","41 år"],["Källstatus","Födelsenotisen låser kopplingen mellan Johannes Arvidssons dödsnotis och Inger Hansdotters familj"]],"story":["Jenny Serafia föds 15 december 1871 och döps 24 december i Årstad.","Födelsenotisen anger fadern som avlidne torparen Johannes Arvidsson under N:o 10 Årstad och modern som Inger Hansdotter. Detta är ett starkt bevis för att Johannes dödsnotis från oktober 1871 hör till samma familj."],"parents":["johannes_andersson_arstad","inger_hansdotter_arstad"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('arvid_ivarsson','arvid-ivarsson','Arvid Ivarsson','Arfvid / Arved Ifvarsson','father',true,false,'public','{"name":"Arvid Ivarsson","alt":"Arfvid / Arved Ifvarsson","role":"Johannes Arvidssons far","born":"1797-09-01","status":"confirmed","place":"Jordsbacka, Okome","facts":[["Döpt","1797-09-03"],["Föräldrar","Ivar Bengtsson och Britta Larsdotter"],["Vigsel","1823-06-24 i Okome med Gunnil Andreasdotter"],["Titel vid vigsel","Tillträdande hemmansåbo"],["Bostadsspår","Jordsbacka; Forsbacka; tidig mönstrings-/Bösarp-post"],["Källstatus","Födelsenotis och vigsel bekräftade i senaste farfarsfilen"]],"story":["Arvid Ivarsson föds 1 september 1797 i Jordsbacka i Okome och döps 3 september. Födelsenotisen anger föräldrarna Ivar Bengtsson och Britta Larsdotter.","Han förekommer tidigt i mönstrings-/Bösarp-spår och som dräng i Forsbacka, men Bösarp ska inte behandlas som födelseplats. Vid vigseln 1823 står han som tillträdande hemmansåbo.","Arvid gifter sig 24 juni 1823 i Okome med Gunnil Andreasdotter. Paret återfinns i Okome med barnen Lars Johan, Anna Beata, Johanna Beata och Johannes Arvidsson."],"timeline":[["1797-09-01","Föds i Jordsbacka, Okome."],["1797-09-03","Döps."],["ca 1818-1820","Förekommer i tidig Bösarp-/mönstringspost."],["före 1823","Står som dräng i Forsbacka."],["1823-06-24","Vigs med Gunnil Andreasdotter i Okome."],["1834-08-06","Sonen Johannes Arvidsson föds i Okome."]],"parents":["ivar_bengtsson_okome","britta_larsdotter_okome"],"children":["lars_johan_arvidsson","anna_beata_arvidsdotter","johanna_beata_arvidsdotter","johannes_andersson_arstad"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('gunnil_andreasdotter','gunnil-andreasdotter','Gunnil Andreasdotter','Gunnill Andreasdr.','father',true,false,'public','{"name":"Gunnil Andreasdotter","alt":"Gunnill Andreasdr.","role":"Johannes Arvidssons mor","born":"1795-08-20","status":"confirmed","place":"Jordsbacka, Okome","facts":[["Vigsel","1823-06-24 i Okome med Arvid Ivarsson"],["Hemort vid vigsel","Jordsbacka"],["Källstatus","Renskrivna Okome-hushåll bekräftar henne som mor i Johannes barndomshushåll"]],"story":["Gunnil Andreasdotter föds enligt Okome-hushållet 20 augusti 1795.","Hon gifter sig 24 juni 1823 i Okome med Arvid Ivarsson. I Okome-hushållen står hon som mor i familjen med barnen Lars Johan, Anna Beata, Johanna Beata och Johannes."],"parents":[],"children":["lars_johan_arvidsson","anna_beata_arvidsdotter","johanna_beata_arvidsdotter","johannes_andersson_arstad"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('lars_johan_arvidsson','lars-johan','Lars Johan',null,'father',false,false,'public','{"name":"Lars Johan","role":"Syskon till Johannes Arvidsson","born":"1826-03-24","status":"confirmed","place":"Okome / Vinberg","facts":[["Flyttnotering","Till Vinberg i november 1844"],["Källstatus","Sannolikt äldre syskon i Okome-hushållet"]],"story":["Lars Johan förekommer som barn i hushållet med Arvid Ivarsson och Gunnil Andreasdotter i Okome.","En flyttnotering visar att han flyttar till Vinberg i november 1844, vilket är intressant eftersom Vinberg senare återkommer i Johannes Arvidssons och Inger Hansdotters kedja."],"parents":["arvid_ivarsson","gunnil_andreasdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_beata_arvidsdotter','anna-beata','Anna Beata',null,'father',false,false,'public','{"name":"Anna Beata","role":"Syskon till Johannes Arvidsson","born":"1829-04-06","status":"confirmed","place":"Okome","facts":[["Källstatus","Sannolikt äldre syskon i Okome-hushållet"]],"story":["Anna Beata förekommer i Okome-hushållet med Arvid Ivarsson och Gunnil Andreasdotter och förs som syster till Johannes Arvidsson."],"parents":["arvid_ivarsson","gunnil_andreasdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johanna_beata_arvidsdotter','johanna-beata','Johanna Beata',null,'father',false,false,'public','{"name":"Johanna Beata","role":"Syskon till Johannes Arvidsson","born":"1832-01-04","status":"confirmed","place":"Okome","facts":[["Flyttnotering","Utflyttad 1846, destination svårläst"],["Källstatus","Sannolikt äldre syskon i Okome-hushållet"]],"story":["Johanna Beata förekommer i Okome-hushållet med Arvid Ivarsson och Gunnil Andreasdotter och förs som syster till Johannes Arvidsson.","Hennes utflyttningsnotis 1846 är ännu svårläst och ska inte låsas till en viss ort."],"parents":["arvid_ivarsson","gunnil_andreasdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('ivar_bengtsson_okome','ivar-bengtsson','Ivar Bengtsson','Ifvar Bengtsson','father',true,false,'public','{"name":"Ivar Bengtsson","alt":"Ifvar Bengtsson","role":"Arvid Ivarssons far","born":"1757-04-21","died":"1833","status":"confirmed","place":"Heden / Jordsbacka / Ögärdet, Okome","facts":[["Döpt","1757-04-24"],["Vigsel","1788-06-22 i Askome med Britta Larsdotter"],["Hemort vid vigsel","Heden, Okome socken"],["Föräldrar","Bengt Arvidsson och Ingerd/Ingrid Grellsdotter"],["Källstatus","Födelsenotis, vigsel och husförhörsspår bekräftar kedjan"]],"story":["Ivar Bengtsson föds 21 april 1757 i Okome och döps 24 april. Födelsenotisen anger fadern Bengt Arvidsson och modern stärks i senaste materialet som Ingerd/Ingrid Grellsdotter.","Han vigs 22 juni 1788 i Askome med Britta Larsdotter. Vid vigseln står han som dräng från Heden i Okome socken.","Ivar och Britta återfinns senare i Okome, bland annat Ögärdet och Gjälsås/Gjalsås, med barnen där Arvid/Arfvid Ivarsson ingår."],"timeline":[["1757-04-21","Föds i Okome."],["1757-04-24","Döps."],["1788-06-22","Vigs med Britta Larsdotter i Askome."],["1797-09-01","Sonen Arvid föds i Jordsbacka, Okome."],["1833","Död enligt Okome AI:3-renskrivning."]],"parents":["bengt_arvidsson_okome","ingerd_grellsdotter"],"children":["arvid_ivarsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('britta_larsdotter_okome','britta-larsdotter','Britta Larsdotter',null,'father',true,false,'public','{"name":"Britta Larsdotter","role":"Arvid Ivarssons mor","born":"1766-11-26","status":"confirmed","place":"Askome / Ytregård / Ögärdet","facts":[["Döpt","1766-11-30 i Askome"],["Föräldrar","Lars Olofsson och Johanna, patronymikon ej låst"],["Vigsel","1788-06-22 i Askome med Ivar Bengtsson"],["Hemort vid vigsel","Ytregård/Ytregården"],["Källstatus","Födelse-/dopnotis i Askome matchar födelsedatumet i senare husförhör; exakt volym/bild/sida och moderns patronymikon återstår"]],"story":["Britta Larsdotters födelsenotis har nu hittats i Askome. Hon föds 26 november 1766 och döps 30 november, vilket matchar det födelsedatum som senare husförhör anger.","Födelsenotisen anger fadern Lars Olofsson och modern Johanna, men moderns patronymikon är ännu svårläst och ska inte låsas.","Vid vigseln 1788 anges Britta som pigan från Ytregård/Ytregården. Hon gifter sig med Ivar Bengtsson och återfinns senare tillsammans med honom i Okome. Arvid Ivarssons födelsenotis 1797 anger Britta Larsdotter som mor."],"timeline":[["1766-11-26","Föds enligt Askome födelse-/dopnotis."],["1766-11-30","Döps i Askome."],["1788-06-22","Vigs med Ivar Bengtsson i Askome."],["1797-09-01","Sonen Arvid Ivarsson föds i Jordsbacka, Okome."]],"parents":["lars_olofsson_askome","johanna_okand_patronymikon_askome"],"children":["arvid_ivarsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('lars_olofsson_askome','lars-olofsson','Lars Olofsson',null,'father',true,false,'public','{"name":"Lars Olofsson","role":"Britta Larsdotters far","status":"confirmed","place":"Askome / Ytregård","facts":[["Barn","Britta Larsdotter, född 1766-11-26 och döpt 1766-11-30 i Askome"],["Maka","Johanna, patronymikon ännu ej låst"],["Källstatus","Bekräftad som far i Britta Larsdotters födelse-/dopnotis K56"]],"story":["Lars Olofsson förs som Britta Larsdotters far utifrån födelse-/dopnotisen i Askome 1766.","Nästa steg är att hitta vigseln med Johanna och följa paret i Askome/Ytregård före och efter Brittas födelse."],"parents":[],"children":["britta_larsdotter_okome"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johanna_okand_patronymikon_askome','johanna','Johanna',null,'father',true,false,'public','{"name":"Johanna","role":"Britta Larsdotters mor","status":"confirmed","place":"Askome / Ytregård","facts":[["Patronymikon","Ej låst; läses som Johanna [svårläst]dotter"],["Barn","Britta Larsdotter, född 1766-11-26 och döpt 1766-11-30 i Askome"],["Make","Lars Olofsson"],["Källstatus","Förnamn bekräftat i Brittas födelse-/dopnotis; patronymikon behöver bättre läsning"]],"story":["Johanna förs som Britta Larsdotters mor utifrån födelse-/dopnotisen i Askome 1766.","Hennes patronymikon är ännu inte säkert läst. Tills en tydligare detalj, renskrivning eller vigselnotis hittas bör hon därför visas som Johanna utan låst efternamn."],"parents":[],"children":["britta_larsdotter_okome"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_arvidsson_okome','bengt-arvidsson','Bengt Arvidsson','Bengt Arfvidsson','father',true,false,'public','{"name":"Bengt Arvidsson","alt":"Bengt Arfvidsson","role":"Ivar Bengtssons far","status":"confirmed","place":"Okome / Gällsås","facts":[["Vigsel","1757-02-25 i Okome med Ingerd/Ingrid Grellsdotter"],["Titel vid vigsel","Dräng"],["Barn","Ivar Bengtsson, född 1757-04-21"],["Källstatus","Vigseln och Ivars födelsenotis bekräftar föräldraparet"],["Fortsatt arbete","Spåret bakåt före 1757 pausas tills nya ledtrådar finns"]],"story":["Bengt Arvidsson, även skriven Arfvidsson, vigs 25 februari 1757 i Okome med Ingerd/Ingrid Grellsdotter.","Kort därefter föds sonen Ivar Bengtsson den 21 april 1757. Kombinationen av vigseln och Ivars födelsenotis gör föräldraparet starkt bekräftat.","I senaste arbetsmaterialet pausas Bengt Arvidsson-spåret bakåt tills vidare, eftersom det riskerar att bli tidskrävande och osäkert utan fler tydliga ledtrådar."],"timeline":[["1757-02-25","Vigs med Ingerd/Ingrid Grellsdotter i Okome."],["1757-04-21","Sonen Ivar Bengtsson föds i Okome."]],"parents":[],"children":["ivar_bengtsson_okome"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('ingerd_grellsdotter','ingerd-ingrid-grellsdotter','Ingerd / Ingrid Grellsdotter','Grillsdotter','father',true,false,'public','{"name":"Ingerd / Ingrid Grellsdotter","alt":"Grillsdotter","role":"Ivar Bengtssons mor","born":"1734-12-07","status":"confirmed","place":"Gällsås / Gjälsås, Okome","facts":[["Vigsel","1757-02-25 i Okome med Bengt Arvidsson"],["Hemort vid vigsel","Gällsås Lars Måns gård"],["Namnvariant","Ingerd/Ingrid, Grellsdotter/Grillsdotter"],["Källstatus","Bekräftas genom kombinationen av Ivars födelsenotis, vigseln 1757 och senare husförhör"]],"story":["Ingerd eller Ingrid Grellsdotter förs nu som bekräftad mor till Ivar Bengtsson.","Namnet varierar i källorna: vigseln anger Ingrid Grellsdotter, medan senare husförhör/renskrivning visar Ingerd Grillsdotter född 7 december 1734. Variantformen Grillsdotter behålls därför som alternativ namnform.","Hon vigs 25 februari 1757 i Okome med Bengt Arvidsson. Sonen Ivar Bengtsson föds 21 april samma år."],"timeline":[["1734-12-07","Född enligt senare husförhör; födelsenotisen behöver tydligare detalj."],["1757-02-25","Vigs med Bengt Arvidsson i Okome."],["1757-04-21","Sonen Ivar Bengtsson föds."]],"parents":[],"children":["ivar_bengtsson_okome"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('elsa_helena_karlsson','elsa-helena','Elsa Helena',null,'father',true,true,'family','{"name":"Elsa Helena","role":"Farmor","born":"1920-09-24","status":"confirmed","place":"Balg nr 3, Torpa","facts":[["Födelseförsamling","Torpa (N)"],["Bostad i barndomen","Balg nr 3, Torpa"],["Tvilling","Karin Linnea"],["Källa","Torpa (N) CI:5 (1917-1944), Bild 110, Sida 7, födelsenotis nr 10"]],"story":["Elsa Helena är Göran Nilssons mor och därmed farmor på Axels fars sida.","Hon föds 24 september 1920 i Torpa och återfinns i familjen på Balg nr 3. Födelsenotisen anger föräldrarna Karl Karlsson och Elemina Karlsdotter.","Elsa Helena är tvilling med Karin Linnea."],"timeline":[["1920-09-24","Föds i Torpa."],["1920","Familjen bor på Balg nr 3 i Torpa."]],"parents":["karl_karlsson","elemina_karlsdotter"],"children":["goran_nilsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('karl_karlsson','karl-karlsson','Karl Karlsson','Carl Karlsson','father',true,false,'public','{"name":"Karl Karlsson","alt":"Carl Karlsson","role":"Elsas far","born":"1884-07-13","status":"confirmed","place":"Balg nr 3, Torpa","facts":[["Döpt","1884-07-18"],["Födelseförsamling","Torpa"],["Yrke/titel","Hemmansägare/hemmansbrukare, behöver verifieras"],["Vigsel","troligen 1914-07-03, behöver verifieras"],["Källa","Torpa födelsebok 1884 och hushållssida för Balg nr 3"]],"story":["Karl Karlsson, även skriven Carl, föds 13 juli 1884 i Torpa och döps 18 juli.","Födelsenotisen anger föräldrarna Carl Bengtsson och Inger Kristina Nilsdotter på Balg nr 3.","Som vuxen återfinns Karl på Balg nr 3 tillsammans med hustrun Elemina Karlsdotter och barnen Nils Lennart, Ingrid Svea Viola, Elsa Helena, Karin Linnea och Sonja Ingeborg."],"timeline":[["1884-07-13","Föds i Torpa."],["1884-07-18","Döps."],["1914-07-03","Trolig vigsel med Elemina Karlsdotter, datum behöver verifieras."],["ca 1916","Familjen flyttar/får flyttningsbetyg till Åby enligt arbetsläsning, behöver verifieras."],["1920","Familjen finns på Balg nr 3 när Elsa Helena föds."]],"parents":["carl_bengtsson","inger_kristina_nilsdotter"],"children":["nils_lennart_karlsson","ingrid_svea_viola_karlsson","elsa_helena_karlsson","karin_linnea_karlsson","sonja_ingeborg_karlsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('elemina_karlsdotter','elemina-karlsdotter','Elemina Karlsdotter',null,'father',true,false,'public','{"name":"Elemina Karlsdotter","role":"Elsas mor","born":"1889-07-31","status":"confirmed","place":"Ås / Balg nr 3, Torpa","facts":[["Födelseförsamling","Ås"],["Vigsel","troligen 1914-07-03 med Karl Karlsson, behöver verifieras"],["Bostad omkring 1920","Balg nr 3, Torpa"],["Nästa steg","Kontrollera födelsenotis i Ås 1889 och identifiera föräldrar"]],"story":["Elemina Karlsdotter föds 31 juli 1889 i Ås enligt församlingsbokssidan.","Hon är gift med Karl Karlsson och återfinns som mor i hushållet på Balg nr 3 i Torpa."],"parents":[],"children":["nils_lennart_karlsson","ingrid_svea_viola_karlsson","elsa_helena_karlsson","karin_linnea_karlsson","sonja_ingeborg_karlsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
