insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('carl_bengtsson','carl-bengtsson','Carl Bengtsson',null,'father',true,false,'public','{"name":"Carl Bengtsson","role":"Karl Karlssons far","born":"1848-10-25","status":"confirmed","place":"Balg nr 3, Torpa","facts":[["Döpt","1848-10-28"],["Födelseförsamling","Torpa"],["Titel","ägare/hemmansägare, läsning behöver verifieras"],["Vigsel","1872-02-22 med Inger Kristina Nilsdotter"],["Källa","Torpa födelsebok 1848 och Torpa AI:3, Bild 69, Sida 27"]],"story":["Carl Bengtsson föds 25 oktober 1848 i Torpa och döps 28 oktober.","Födelsenotisen anger honom som son till åbo Bengt Olsson på Balg nr 3 och hustrun Helena Svensdotter.","Som vuxen finns Carl Bengtsson på Balg nr 3 tillsammans med hustrun Inger Kristina Nilsdotter och flera barn, däribland Karl/Carl Karlsson."],"parents":["bengt_olsson","helena_svensdotter"],"children":["leonard_karlsson","anna_brita_carlsdotter","brita_helena_carlsdotter","karl_karlsson","johan_carlsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('inger_kristina_nilsdotter','inger-kristina-nilsdotter','Inger Kristina Nilsdotter','Inga Christina Nilsdotter','father',true,false,'public','{"name":"Inger Kristina Nilsdotter","alt":"Inga Christina Nilsdotter","role":"Karl Karlssons mor","born":"1848-03-03","status":"confirmed","place":"nr 9 Torpa / Balg nr 3, Torpa","facts":[["Döpt","1848-03-05"],["Födelseförsamling","Torpa"],["Tidigare hushållsläsning","1848-03-15 förekommer, korrigerat mot födelsenotis"],["Vigsel","1872-02-22 med Carl Bengtsson"],["Källa","Torpa födelsebok 1848"]],"story":["Inger Kristina Nilsdotter föds 3 mars 1848 i Torpa och döps 5 mars.","Födelsenotisen anger henne som dotter till arrendatorn Nils Nilsson på nr 9 Torpa och hustrun Anna Britta Nilsdotter.","Hon återfinns senare på Balg nr 3 tillsammans med maken Carl Bengtsson."],"parents":["nils_nilsson_torpa","anna_brita_nilsdotter_torpa"],"children":["leonard_karlsson","anna_brita_carlsdotter","brita_helena_carlsdotter","karl_karlsson","johan_carlsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
