insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_olsson','bengt-olsson','Bengt Olsson',null,'father',true,false,'public','{"name":"Bengt Olsson","role":"Carl Bengtssons far","born":"1816-11-08","status":"confirmed","place":"Balg nr 3, Torpa","facts":[["Döpt","1816-11-10"],["Titel","åbo"],["Avvikande datum","Husförhör/BiS anger 1816-11-07"],["Källa","Torpa födelsebok 1816 och Torpa AI:3, Bild 69, Sida 27"]],"story":["Bengt Olsson föds 8 november 1816 i Torpa och döps 10 november. Arbetsdatumet bygger på födelsenotisen, även om husförhör/BiS anger 7 november.","Födelsenotisen anger föräldrarna Olof Berntsson och Hilla Pehrsdotter i Balg.","Som vuxen återfinns Bengt på Balg tillsammans med hustrun Helena Svensdotter och barnen Anna Helena, Johanna Christina och Carl."],"parents":["olof_berntsson","hilla_pehrsdotter"],"children":["anna_helena_bengtsdotter","johanna_christina_bengtsdotter","carl_bengtsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('helena_svensdotter','helena-svensdotter','Helena Svensdotter',null,'father',true,false,'public','{"name":"Helena Svensdotter","role":"Carl Bengtssons mor","born":"1821-04-01","status":"confirmed","place":"Balg nr 3, Torpa","facts":[["Källa","Torpa AI:3 (1835-1849), Bild 69, Sida 27"],["Nästa steg","Bekräfta födelsedatum i födelsebok och identifiera föräldrar"]],"story":["Helena Svensdotter är hustru till Bengt Olsson och mor till Carl Bengtsson.","Hon återfinns på Balg i Torpa tillsammans med Bengt och barnen Anna Helena, Johanna Christina och Carl."],"parents":[],"children":["anna_helena_bengtsdotter","johanna_christina_bengtsdotter","carl_bengtsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
