insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('olof_berntsson','olof-berntsson','Olof Berntsson',null,'father',true,false,'public','{"name":"Olof Berntsson","role":"Bengt Olssons far","born":"1783-03-20","status":"confirmed","place":"Balg, Torpa","facts":[["Döpt","1783-03-21"],["Titel","åbo"],["Källa","Torpa födelsebok 1783 och Torpa AI:1 (1806-1826), Bild 85, Sida 130"]],"story":["Olof Berntsson föds 20 mars 1783 i Torpa och döps 21 mars.","Födelsenotisen anger föräldrarna Berndt/Bernt Börgesson och Ingeborg Olofsdotter i Balg.","Olof återfinns i hushållet på Balg tillsammans med Hilla Pehrsdotter och barnen Johanna Britta, Kerstin och Bengt."],"parents":["bernt_borgesson","ingeborg_olofsdotter"],"children":["johanna_britta_olofsdotter","kerstin_olofsdotter","bengt_olsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('hilla_pehrsdotter','hilla-pehrsdotter','Hilla Pehrsdotter',null,'father',true,false,'public','{"name":"Hilla Pehrsdotter","role":"Bengt Olssons mor","born":"1784-11-17","status":"confirmed","place":"Balg, Torpa","facts":[["Källa","Torpa AI:1 (1806-1826), Bild 85, Sida 130"],["Nästa steg","Bekräfta födelsedatum i födelsebok och kontrollera vigsel med Olof Berntsson"]],"story":["Hilla Pehrsdotter återfinns i hushållet på Balg tillsammans med Olof Berntsson och barnen Johanna Britta, Kerstin och Bengt.","Husförhör/BiS anger födelsedatumet 17 november 1784, vilket ska bekräftas i födelsebok."],"parents":[],"children":["johanna_britta_olofsdotter","kerstin_olofsdotter","bengt_olsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johanna_britta_olofsdotter','johanna-britta-olofsdotter','Johanna Britta Olofsdotter',null,'father',false,false,'public','{"name":"Johanna Britta Olofsdotter","role":"Syskon till Bengt Olsson","born":"1812-09-16","status":"confirmed","place":"Balg, Torpa","story":["Johanna Britta förekommer som dotter i hushållet med Olof Berntsson och Hilla Pehrsdotter på Balg."],"parents":["olof_berntsson","hilla_pehrsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('kerstin_olofsdotter','kerstin-olofsdotter','Kerstin Olofsdotter',null,'father',false,false,'public','{"name":"Kerstin Olofsdotter","role":"Syskon till Bengt Olsson","born":"1815-04-14","status":"confirmed","place":"Balg, Torpa","story":["Kerstin förekommer som dotter i hushållet med Olof Berntsson och Hilla Pehrsdotter på Balg."],"parents":["olof_berntsson","hilla_pehrsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('borge_borgesson','borge-borgesson','Börge Börgesson','Börjesson','father',true,false,'public','{"name":"Börge Börgesson","alt":"Börjesson","role":"Berndt/Bernt Börgessons far","status":"confirmed","place":"Sällstorp / Balg, Torpa","facts":[["Vigsel","1753-02-07 med Kierstin/Kerstin Jönsdotter"],["Hemort vid vigsel","Dräng i Sällstorp enligt korrigerad läsning"],["Barn","Bernd/Bernt född 1753-11-28 i Balg"],["Mantalsfynd","1756 finns en stark notering under Balg som läses Börge Börgson/Börgesson"],["Källstatus","Födelsenotisen för Bernd/Bernt 1753 och vigseln 1753 gör föräldrakopplingen bekräftad i arbetsmaterialet"],["Avfört spår","Tidigare möjlig dödsnotis 1755 ska inte användas som stöd"]],"story":["Börge Börgesson eller Börjesson förs nu som bekräftad far till Berndt/Bernt Börgesson i Balg.","Vigselnotisen 1753-02-07 kopplar honom till Kierstin/Kerstin Jönsdotter. Den korrigerade läsningen anger Börge som dräng i Sällstorp, medan Kierstin hade koppling till Balg. Det förklarar varför Börge kan vara svår att hitta i Balg före vigseln.","Sonen Bernd/Bernt föds 28 november 1753 i Balg. Ett mantalsfynd 1756 under Balg, läst som Börge Börgson/Börgesson, stöder att Börge fanns i Balg några år efter vigseln och sonens födelse. Den tidigare möjliga dödsnotisen 1755 har skrotats och ska inte användas som stöd."],"timeline":[["1752","Möjlig dräng Börge/Börje i Sällstorp under Anders Anderssons hushåll; patronymikon mycket osäkert."],["1753-02-07","Vigs med Kierstin/Kerstin Jönsdotter. Börge läses som dräng i Sällstorp."],["1753-11-28","Sonen Bernd/Bernt föds i Balg, Torpa."],["1756","Mantalslängden visar starkt stöd för Börge Börgson/Börgesson under Balg-post."],["1757","Noteringen tolkas som Balg Börgesgård/Balg Börgesg., inte som säker personrad för Börge."]],"parents":[],"children":["bernt_borgesson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('kierstin_jonsdotter','kierstin-kerstin-jonsdotter','Kierstin / Kerstin Jönsdotter',null,'father',true,false,'public','{"name":"Kierstin / Kerstin Jönsdotter","role":"Berndt/Bernt Börgessons mor","status":"confirmed","place":"Balg, Torpa","facts":[["Vigsel","1753-02-07 med Börge Börgesson/Börjesson"],["Hemort","Balg enligt korrigerad vigselläsning"],["Barn","Bernd/Bernt född 1753-11-28 i Balg"],["Källstatus","Föräldrakopplingen till Bernd/Bernt behandlas som bekräftad i arbetsmaterialet"],["Nästa steg","Sök dödsnotis, fler barn, mantal och bouppteckning"]],"story":["Kierstin eller Kerstin Jönsdotter förs nu som bekräftad mor till Berndt/Bernt Börgesson i Balg.","Hon kopplas till Börge Börgesson/Börjesson genom vigselnotisen 1753 och till Bernd/Bernt genom födelsenotisen senare samma år. Den korrigerade läsningen gör henne till Balg-kopplingen i paret, medan Börge står som dräng i Sällstorp.","Eftersom Balg-källorna före 1751 är begränsade bör hennes äldre ursprung i nästa steg sökas via bredare Torpa-sökning, mantal, dödnotis och eventuella bouppteckningar."],"timeline":[["1753-02-07","Vigs med Börge Börgesson/Börjesson."],["1753-11-28","Sonen Bernd/Bernt föds i Balg."]],"parents":[],"children":["bernt_borgesson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bernt_borgesson','berndt-bernt-borgesson','Berndt / Bernt Börgesson','Börjesson','father',true,false,'public','{"name":"Berndt / Bernt Börgesson","alt":"Börjesson","role":"Olof Berntssons far","born":"1753-11-28","status":"confirmed","place":"Balg, Torpa","facts":[["Döpt","1753-12-02"],["Föräldrar","Börge Börgesson/Börjesson och Kierstin/Kerstin Jönsdotter"],["Vigsel","1775-02-19 i Torpa"],["Maka","Ingeborg Olofsdotter från Stomgården"],["Barn","Bengt, Kirstin, Johanna och Olof, alla födda i Balg"],["Namnnotering","Vigselnotisen skriver Börgesson, ArkivDigital normerar till Börjesson"],["Källa","Torpa CI:1 (1691-1810), Bild 650, Sida 125 samt födelsenotiser för barnen i Torpa CI:1"]],"story":["Berndt eller Bernt Börgesson föds 28 november 1753 i Balg och döps 2 december. Födelsenotisen anger föräldrarna Börge Börgesson/Börjesson och Kierstin/Kerstin Jönsdotter.","Han vigs 19 februari 1775 i Torpa med pigan Ingeborg Olofsdotter från Stomgården. Han anges själv som dräng i Balg.","Paret får barnen Bengt, Kirstin, Johanna och Olof i Balg mellan 1776 och 1783. Faddermaterialet pekar mot återkommande kopplingar i Balg och Torpa, särskilt Karin Börgesdotter och Jöns Börgesson som möjliga släktspår.","v28 prioriterar nu mantal och bouppteckningar för att följa övergången från Börge till Berndt i Balg, särskilt åren 1775-1776 och bryggan från 1750-talet till första husförhörslängden 1806."],"timeline":[["1753-11-28","Föds i Balg, Torpa."],["1753-12-02","Döps."],["1775-02-19","Vigs med Ingeborg Olofsdotter från Stomgården."],["1776-01-18","Sonen Bengt föds i Balg."],["1778-11-23","Dottern Kirstin föds i Balg."],["1782-01-02","Dottern Johanna föds i Balg."],["1783-03-20","Sonen Olof föds i Balg."]],"parents":["borge_borgesson","kierstin_jonsdotter"],"children":["bengt_berntsson","kirstin_berntsdotter","johanna_berntsdotter","olof_berntsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('ingeborg_olofsdotter','ingeborg-olofsdotter','Ingeborg Olofsdotter',null,'father',true,false,'public','{"name":"Ingeborg Olofsdotter","role":"Olof Berntssons mor","status":"confirmed","place":"Stomgården / Balg, Torpa","facts":[["Vigsel","1775-02-19 i Torpa"],["Hemort vid vigsel","Stomgården"],["Make","Berndt/Bernt Börgesson/Börjesson"],["Barn","Bengt, Kirstin, Johanna och Olof"],["Källa","Torpa CI:1 (1691-1810), Bild 650, Sida 125"]],"story":["Ingeborg Olofsdotter anges vid vigseln 1775 som piga från Stomgården. Efter vigseln kopplas hon till Balg tillsammans med Berndt/Bernt Börgesson.","Hon är mor till barnen Bengt, Kirstin, Johanna och Olof Berntsson/Olofsdotter, födda i Balg mellan 1776 och 1783.","Hennes ursprung före vigseln från Stomgården är ett viktigt fortsatt forskningsspår."],"parents":[],"children":["bengt_berntsson","kirstin_berntsdotter","johanna_berntsdotter","olof_berntsson"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('bengt_berntsson','bengt-berntsson','Bengt Berntsson',null,'father',false,false,'public','{"name":"Bengt Berntsson","role":"Syskon till Olof Berntsson","born":"1776-01-18","status":"confirmed","place":"Balg, Torpa","facts":[["Döpt","1776-01-21"],["Källa","Torpa CI:1, Bild 720, Sida 139"],["Faddrar","Bland andra Anders Olofsson i Torpa Tolsgård/Tolfsgård, Hindrich Larsson i Balg, Erik Nilsson i Balg och Karin Börgesdotter i Torpa Tolsgård/Tolfsgård; flera läsningar är preliminära"]],"story":["Bengt föds 18 januari 1776 i Balg som barn till Berndt/Bernt Börgesson och Ingeborg Olofsdotter.","Faddrarna är viktiga för att förstå nätverket kring Balg. Karin Börgesdotter är särskilt intressant eftersom patronymikonet kan tyda på släktkoppling till Berndt/Bernt."],"parents":["bernt_borgesson","ingeborg_olofsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('kirstin_berntsdotter','kirstin-berntsdotter','Kirstin Berntsdotter',null,'father',false,false,'public','{"name":"Kirstin Berntsdotter","role":"Syskon till Olof Berntsson","born":"1778-11-23","status":"confirmed","place":"Balg, Torpa","facts":[["Döpt","1778-11-23"],["Källa","Torpa CI:1, Bild 780, Sida 151"],["Faddrar","Bland andra Anders Svensson i Balg, Pähr Andersson i Balg, Lars Larsson i Balg, Pernilla Olofsdotter i Torpa, Hilla Eliasdotter i Torpa och Ingegärd Mathisdotter i Balg"]],"story":["Kirstin föds och döps 23 november 1778 i Balg som dotter till Berndt/Bernt Börgesson och Ingeborg Olofsdotter.","Fadderlistan stärker bilden av ett tätt Balg-/Torpa-nätverk som behöver följas vidare."],"parents":["bernt_borgesson","ingeborg_olofsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('johanna_berntsdotter','johanna-berntsdotter','Johanna Berntsdotter',null,'father',false,false,'public','{"name":"Johanna Berntsdotter","role":"Syskon till Olof Berntsson","born":"1782-01-02","status":"confirmed","place":"Balg, Torpa","facts":[["Döpt","1782-01-03"],["Källa","Torpa CI:1, Bild 910, Sida 177"],["Faddrar","Bland andra Jöns Börgesson i Torpa, Anders Hellersson/Hallersson i Gunnestorp, Kirstin Olofsdotter i Balg, Anna Larsdotter i Balg och Anna Andersdotter i Balg; flera läsningar är preliminära"]],"story":["Johanna föds 2 januari 1782 i Balg som dotter till Berndt/Bernt Börgesson och Ingeborg Olofsdotter.","Faddern Jöns Börgesson är särskilt intressant eftersom han kan vara bror eller nära släkting till Berndt/Bernt, men detta är ännu inte bevisat."],"parents":["bernt_borgesson","ingeborg_olofsdotter"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('jons_borgesson','jons-borgesson','Jöns Börgesson',null,'father',false,false,'public','{"name":"Jöns Börgesson","role":"Kandidatspår vid Balg","status":"working","place":"Balg / Torpa Stomgård","facts":[["Vigsel","1777-12-22 med Petronella Olofsdotter"],["Hemort","Dräng från Balg"],["Koppling","Förekommer som fadder i Berndt/Bernts familj"],["Forskningsvärde","Kan vara bror eller nära släkting till Berndt/Bernt Börgesson, men detta är inte bevisat"],["Status","Sidospår, släktskap ej bevisat"]],"story":["Jöns Börgesson är ett viktigt sidospår eftersom han förekommer som fadder i familjen Berndt/Bernt Börgesson och Ingeborg Olofsdotter.","Han vigs 22 december 1777 som dräng från Balg med pigan Petronella Olofsdotter, troligen med koppling till Torpa Stomgård/Stomg. Kopplingen till både Balg och Stomgården gör honom extra intressant eftersom Ingeborg Olofsdotter också kom från Stomgården.","v28 lyfter Jöns och Karin Börgesdotter som prioriterade kontrollpersoner i fadder- och mantalsarbetet, men någon släktkoppling är ännu inte bevisad."],"parents":[],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('petronella_olofsdotter','petronella-olofsdotter','Petronella Olofsdotter',null,'father',false,false,'public','{"name":"Petronella Olofsdotter","role":"Kandidatspår vid Stomgården","status":"working","place":"Torpa Stomgård","facts":[["Vigsel","1777-12-22 med Jöns Börgesson"],["Status","Sidospår, möjlig Stomgården-koppling behöver verifieras"]],"story":["Petronella Olofsdotter vigs 1777 med Jöns Börgesson från Balg. Hennes hemort läses preliminärt som Torpa Stomgård eller Stomg.","Eftersom Ingeborg Olofsdotter också kom från Stomgården är Petronella ett intressant kontrollspår, men någon släktkoppling är ännu inte bevisad."],"parents":[],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('nils_nilsson_torpa','nils-nilsson','Nils Nilsson',null,'father',true,false,'public','{"name":"Nils Nilsson","role":"Inger Kristinas far","status":"confirmed","place":"nr 9 Torpa","facts":[["Titel","arrendator"],["Maka","Anna Britta Nilsdotter"],["Källa","Födelsenotis för Inger Kristina Nilsdotter, 1848-03-03"]],"story":["Nils Nilsson är far till Inger Kristina Nilsdotter enligt hennes födelsenotis 1848.","Han anges som arrendator på nr 9 Torpa. Hans eget födelsedatum och föräldrar är ännu inte kartlagda."],"parents":[],"children":["inger_kristina_nilsdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('anna_brita_nilsdotter_torpa','anna-britta-nilsdotter','Anna Britta Nilsdotter',null,'father',true,false,'public','{"name":"Anna Britta Nilsdotter","role":"Inger Kristinas mor","status":"confirmed","place":"nr 9 Torpa","facts":[["Make","Nils Nilsson"],["Källa","Födelsenotis för Inger Kristina Nilsdotter, 1848-03-03"]],"story":["Anna Britta Nilsdotter är mor till Inger Kristina Nilsdotter enligt födelsenotisen 1848.","Familjen är kopplad till nr 9 Torpa. Hennes eget födelsedatum och föräldrar är ännu inte kartlagda."],"parents":[],"children":["inger_kristina_nilsdotter"]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('axel_nilsson','axel-nilsson','Axel Nilsson',null,'shared',true,true,'family','{"name":"Axel Nilsson","born":"1996-01-03","status":"confirmed","role":"Bygger trädet","story":["Axel Nilsson föds 3 januari 1996, barn till Gerd Bengtsson och Göran Nilsson. Det är Axel som bygger detta släktträd."],"parents":["gerd_bengtsson","goran_nilsson"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,content) values('ebba_nilsson','ebba-nilsson','Ebba Nilsson',null,'shared',false,true,'family','{"name":"Ebba Nilsson","born":"1998-05-26","status":"confirmed","role":"Syskon","story":["Ebba Nilsson föds 26 maj 1998, barn till Gerd Bengtsson och Göran Nilsson."],"parents":["gerd_bengtsson","goran_nilsson"],"children":[]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,alt_name=excluded.alt_name,branch=excluded.branch,is_direct=excluded.is_direct,is_living=excluded.is_living,visibility=excluded.visibility,content=excluded.content;
insert into public.places(id,slug,name,area,latitude,longitude,visibility,content) values('traslov','traslov','Träslöv','Halland',57.089,12.293,'public','{"id":"traslov","name":"Träslöv","area":"Halland","lat":57.089,"lng":12.293,"zoom":13,"aliases":["Träslöv","Träslöf","Träslöfs By"],"note":"Central församling i morfars Bengtssonlinje. Här finns Olof Svensgård, Wahlagården/Jon Nilsgård och flera födelse-, vigsel- och husförhörsposter."}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,area=excluded.area,latitude=excluded.latitude,longitude=excluded.longitude,visibility=excluded.visibility,content=excluded.content;
insert into public.places(id,slug,name,area,latitude,longitude,visibility,content) values('wahlagarden','wahlagarden-valagarden-jon-nilsgard','Wahlagården / Valagården / Jon Nilsgård','Träslöv nr 5',null,null,'public','{"id":"wahlagarden","name":"Wahlagården / Valagården / Jon Nilsgård","area":"Träslöv nr 5","aliases":["Wahlagården","Valagården","Välagården","Wahlagård","Valagård","Träslöf Valagård","Jon Nilsgård","John Nilsgård","Jöns Nilsgård","Joen Nilsgård","N:o 5 Jon Nilsgård","Wahlagården Jon Nilsgård","Träslöv N:o 5","Jon Nils Hemman","Joen Nilsgård","Träslöv nr 5 Valagården","Träslöv 5:3 Valagården","Träslöv 5:6","Träslöv 5:7","Hwalagården","Joen Nielsons gård"],"note":"Gård i morfarslinjen. V89 stärker tolkningen att Wahlagården/Valagården och Jon/Jöns Nilsgård avser samma gårdsenhet i Träslöv nr 5. Kedjan går från Mårten Andersson och Helena Jönsdotter via Anna Mårtensdotter och Olof Andersson till Anna Olofsdotter, Bengta Börjesdotter och familjen Bengt Olofsson/Bengta Börjesdotter vid Wahlagården/Jon Nilsgård.","facts":[["Gårdsidentitet","Jöns/Jon/Joen Nilsgård, Jon Nils Hemman, Wahlagården, Valagården och Välagården behandlas som samma gårdsmiljö i Träslöv nr 5."],["Säker huvudkedja","Mårten Andersson + Helena Jönsdotter → Anna Mårtensdotter + Olof Andersson → Anna Olofsdotter + Börje Pehrsson → Bengta Börjesdotter + Bengt Olofsson."],["Källstatus","Stark gårdskontinuitet från 1762 till 1820. Äldre spår omkring 1700 är viktiga men fortsatt källkritiska."],["1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare och beskriver Valagård som cirka 12 hektar stort jordbruk."],["Källnivåer","Originalhandlingar och kontrollerade kyrkböcker hålls åtskilda från familjeavskrifter, register, sekundär forskning och hypoteser."],["Äldre namn","Hallands Släktforskarförenings register anger Joen Nilsgård som namn år 1645 för Träslöv nr 5."],["Jordnatur","En familjeavskrift uppger klosterhemman 1649 och senare kronohemman. Bakomliggande originalkälla är ännu inte identifierad."],["Landsbeskrivning 1729","Familjens avskrift beskriver Joen Nielsons gård som ett kronohemman om 3/4 mantal, delat mellan Swen Andersson och Anders Mårtenssons änka med 3/8 mantal vardera."],["Laga skifte 1839","Familjens avskrift anger tre åbor: Börje Larsson 3/16 mantal, Nils Börjesson 3/16 mantal och Bengt Olsson 3/8 mantal."],["Gårdsmiljö 1857","Familjeanteckningarna anger 37 personer i sex hushåll samt ett jordtorp och en backstuga inom Träslöv nr 5."],["Byggnader 1866","Familjens avskrift för Träslöv 5:6 beskriver delning av ett förfallet halmtäckt boningshus och ladugård mellan Petter Anders Svensson och Bengt August Nilsson."],["Ekonomiska handlingar","Skuldebrev och inteckningar 1888-1912 berör andelar i Träslöv nr 5, men varje andels exakta samband med familjens del av Valagården är inte slutligt klarlagt."],["Jordbruk 1915","Valagård omfattade 12,00 hektar, varav 11,50 hektar odlad jord. Djurbeståndet omfattade bland annat två arbetshästar, ett föl, ungnöt, kalv, grisar och 25 höns."],["Fastighetsdelar","Materialet nämner bland annat Träslöv 5:3, 5:6 och 5:7. De ska inte behandlas som identiska utan fortsatt kontroll av avstyckningar och ägogränser."],["Arrende 1958-1963","Originalkontraktet visar att Lars Emil Bengtsson ägde Träslöv 5:7 och arrenderade ut fastigheten till brorsonen Harry Bengtsson för 900 kronor per år."]],"story":["Valagård/Wahlagården är en av de viktigaste gårdsmiljöerna i morfars Bengtssonlinje. I källorna växlar namnen mellan Jöns Nilsgård, Jon Nilsgård, Joen Nilsgård, Wahlagården, Valagården och Välagården, men v89-underlaget behandlar dem som samma gårdsenhet i Träslöv nr 5.","Den säkra släktkedjan börjar med att Mårten Andersson och Helena Jönsdotter är belagda vid Jöns Nilsgård genom Mårtens död och bouppteckning 1762. Deras dotter Anna Mårtensdotter gifter sig med Olof Andersson från Dagsås och dottern Anna Olofsdotter föds på Jon Nilsgård 1767.","Gården fortsätter sedan genom Anna Olofsdotter och Börje Pehrsson till Bengta Börjesdotter. När Bengta gifter sig med Bengt Olofsson 1813 anges hon komma från Wahlagården, och barnens födelsenotiser 1814-1820 visar att Wahlagården och Jon Nilsgård används parallellt för samma miljö.","Det äldre materialet kring N:o 42 Jon Nils Hemman och Träslöv N:o 5 för gårdshistorien bakåt mot 1600- och tidigt 1700-tal. Där finns starka gårdsspår, men vissa personkopplingar ska hållas som hypoteser tills fler originalkällor är säkrade.","Den nya Valagården-mastern skiljer uttryckligen mellan originalhandlingar, familjens avskrifter, index och register, sekundär forskning samt hypoteser. Gårdens historia redovisas därför med olika säkerhetsnivåer: en senare gårdsanknytning innebär exempelvis inte automatiskt att personen föddes där eller ägde marken.","Gårdsregistret för Träslöv nr 5 anger Joen Nilsgård som äldre namn år 1645. Familjens bevarade gårdsanteckningar uppger dessutom att gården var klosterhemman 1649 och senare kronohemman. Den uppgiften är värdefull men vilar ännu på en familjeavskrift vars bakomliggande original måste identifieras.","Omkring år 1700 visar det äldre materialet två skilda hushållsgrupper vid Jon Nils hemman. I den första finns Anders Andersson, Karin Olsdotter/Olofsdotter och barnen Olof, Börje och Kirsti/Kerstin Andersdotter. Den femåriga personen har tidigare lästs som Mårten Andersson, men den läsningen är korrigerad. I en andra grupp finns Börje Nilsson med hustru och flera barn. Grupperna visar gårdsmiljön men får inte utan ytterligare belägg kopplas till huvudlinjens Mårten Andersson.","Familjens avskrift av 1729 års landsbeskrivning ger en konkret bild av Joen Nielsons gård som ett kronohemman om tre fjärdedels mantal, delat mellan två åbor. Där fanns två stugor med förstugor, härbärgen, brygghus, uthus, torvhus och vagnskjul, en liten trädgård med äppelträd samt två kålhagar. Swen Andersson uppges ha tillträtt sin andel 1699 och Anders Mårtenssons änka sin andel 1722. Uppgifterna behöver fortfarande kontrolleras mot landsbeskrivningens original.","Den första säkra och tydligt dokumenterade kopplingen för den direkta linjen är Mårten Andersson och Helena Jönsdotter vid Jöns Nilsgård 1762. Därefter kan boende- och släktkontinuiteten följas genom Anna Mårtensdotter, Anna Olofsdotter och Bengta Börjesdotter till Bengt Olofsson och barnen. Mönstret talar för att gårdsanknytningen kan ha följt kvinnolinjen, men det bevisar inte privat ägande eller exakt brukningsrätt.","Kartavskrifter från 1823 och 1840 visar flera gårdslägen inom Träslöv nr 5. Inför laga skiftet 1839 brukade Börje Larsson och Nils Börjesson vardera tre sextondels mantal, medan Bengt Olsson brukade tre åttondels mantal. Nils Börjesson och Bengt Olsson uppges ha haft en gård tillsammans, medan Börje Larssons bebyggelse låg avskilt. År 1857 fanns enligt familjeanteckningarna 37 personer i sex hushåll samt jordtorp och backstuga.","En familjeavskrift av en förrättning den 4 juli 1866 beskriver Valagården Träslöv 5:6 i ovanlig detalj. Det halmtäckta boningshuset var 61 fot långt och rymde stuga, förstuga, härbärge, kammare och kök. Byggnaderna var förfallna och delades mellan Petter Anders Svensson och Bengt August Nilsson. Tolkningen att Petter skulle flytta och Bengt August stanna kvar är stark men behöver jämföras med originalhandlingen.","Ekonomiska handlingar visar flera skilda andelar i Träslöv nr 5. Alfred Sundgren intecknade 3/64 mantal 1888. Bengt August Nilsson den äldre tog 1901 ett lån på 1 600 kronor med en indirekt säkerhet knuten till 3/64 mantal Jöns Nilsgård; räntebetalningar kan följas till 1911. Handlingarna belyser gårdens ekonomi men bevisar inte att alla nämnda andelar motsvarade samma brukningsdel.","Lokalundersökningen 1915 visar Valagård som ett intensivt brukat jordbruk på 12 hektar, nästan helt odlat. Där odlades spannmål, potatis, foderrotfrukter, hö och grönfoder, och gården hade hästar, nötkreatur, grisar och höns. Bengt Nilsson den äldre står i ägarfältet, men blanketten avgör inte om Sara Britta Andersdotter hade en juridisk andel.","Familjens material från 1920-talet visar flera åbor och yrkesarbetande barn inom den äldre gårdsmiljön. Ett originalskuldebrev från 1928 visar dessutom att Lars Emil Bengtsson, under namnet Emil Bengtsson och adressen nr 5 Träslöv, erkände en skuld på 3 000 kronor till brodern Sven Adolf Bengtsson i Klastorp. Räntan anges löpa från 1920, vilket kan tyda på ett äldre lån men ännu är en tolkning.","Svenska Gods och Gårdar 1939 och 1946 återger två olika ägarlängder för Träslöv 5:3 Valagården. En går genom Bengt Olsson, Nils Bengtsson, Bengt August Nilsson och Lars Emil Bengtsson; en annan genom Karl Andersson, Emil Johansson, Algot Leonard Andersson och Sten Andersson. Skillnaden bevaras som en öppen fråga och får inte jämnas ut utan kontroll av utgåvor, brukningsdelar och tidsskeden.","Arvskiftet efter Alma Josefina Bengtsson 1955 placerar Lars Emil Bengtsson på Valagården och dokumenterar syskon och amerikanska arvingar. Ett originalkontrakt från 1958 visar sedan att Lars Emil, som skrev sig Emil Bengtsson, ägde Träslöv 5:7 och arrenderade ut fastigheten till brorsonen Harry Bengtsson till 1963. Emil behöll Smedlyckan bakom ladan för eget bruk, medan Harry fick bruka jorden och använda lada och loge."],"timeline":[["ca 1699-1702","Daterade anteckningar knyter Sven Andersson, Inger Olsdotter och en möjlig tidig familjemiljö till Valagård/Jon Nils Hemman. Detta är ett viktigt äldre gårdsspår men inte hela vägen låst till huvudlinjen."],["1700","N:o 42 ''Jon Nils Hemman i Träslöf'' bedöms höra till Jon/Jöns/Joen Nilsgård = Wahlagård/Valagård. Viktig korrigering: den femåriga personen läses som Kirsti/Kerstin Andersdotter, inte Mårten Andersson."],["1707","En post för Träslöv N:o 5 har identifierats som tidigt belägg för gårdsnumret bakom Jöns/Jon Nilsgård och senare Wahlagården/Valagården. Personerna i utsnittet är ännu inte säkert identifierade."],["1762-07-27","Mårten Andersson dör vid Jöns Nilsgård av bröstfeber. Bouppteckningen 1762-10-21 nämner änkan Helena Jönsdotter och åtta barn."],["1765-02-10","Anna Mårtensdotter från Träslöv Jön Nilsgård gifter sig med Olof Andersson från Dagsås. Olof kommer därmed in i gårdsmiljön genom äktenskapet."],["1767-06-17","Anna Olofsdotter föds vid Jon Nilsgård som dotter till Olof Andersson och Anna Mårtensdotter."],["1787-1800","Husförhör placerar Olof Andersson, Anna Mårtensdotter, Anna Olofsdotter och Börje Pehrsson i hushållsmiljön vid N:o 5 Jon Nilsgård."],["1790-12-26","Anna Olofsdotter från Träslöf Valagård gifter sig med Börje Pehrsson från Klastorps Buragård."],["1800-10-13","Bouppteckningen efter Helena Jönsdotter förrättas vid N:o 5 Jon Nilsgård och nämner dottern Anna, gift med Olof Andersson."],["1813-1820","Namnen Wahlagården och Jon/John Nilsgård används parallellt: Bengta Börjesdotter anges från Wahlagården 1813, barn föds vid Wahlagård 1814-1816 och vid John/Jon Nilsgård 1818-1820."],["1915-08-31","Lokalundersökningsblanketten för Valagård anger Bengt Nilsson d.ä. som ägare. Gården omfattar cirka 12 hektar, med omkring 11,5 hektar odlad jord och tydlig spannmåls-, potatis-, foderväxt- och höproduktion."],["1645","Gårdsregistret anger Joen Nilsgård som äldre namn för Träslöv nr 5."],["1649","Familjens avskrift uppger att gården var klosterhemman och senare blev kronohemman; originalkällan återstår."],["1718","Familjens gårdsanteckningar nämner ''Swen Hwahl och Ingri av Hwalagården''. Identifikationen med Swen Andersson och Inger Olsdotter är ännu en hypotes."],["1729","Familjens avskrift av landsbeskrivningen visar två åbor på Joen Nielsons gård och beskriver byggnader, trädgård, åker, äng och samfälld betesmark."],["1731-04-25","Mårten Andersson och Helena Jönsdotter vigs. Notisen anger Träslövs by respektive Skultagården och är inte ett säkert Valagårdsbelägg."],["1740-08-08","Nils Mårtensson anges i sekundär forskning vara född på Valagård; originalnotisen är ännu inte kontrollerad."],["ca 1756-1759","Husförhör under Jon Nilsgård visar Mårten Anderssons och Börge Anderssons hushåll. En tidigare marginaltolkning om flytt till Walegård är korrigerad till sannolikt Falkenberg."],["1812-1829","Husförhöret Träslöv AI:5 har rubriken ''Wahlagården Jon Nilsgård'', ett direkt belägg för parallell namnanvändning."],["1823","Familjens handritade kartavskrift visar flera husgrupper på Träslöv 5 Jon Nilsgård."],["1839","Förarbetena till laga skiftet beskriver tre åbor och gårdens tre brukningsandelar."],["1840","En kartavskrift markerar gårdslägen för Bengt Olsson, Nils Börjesson och Börje Larsson."],["1857","Familjeanteckningarna anger 37 personer i sex hushåll, ett jordtorp och en backstuga inom Träslöv nr 5."],["1866-07-04","Boningshus och ladugård på Träslöv 5:6 delas mellan Petter Anders Svensson och Bengt August Nilsson enligt en familjeavskrift."],["1888-05-09","Alfred Sundgren belånar 3/64 mantal kronoskatte Träslöv nr 5; dokumentet fastställer inte vilken senare brukningsdel andelen motsvarar."],["1901-04-04","Bengt August Nilsson den äldre utfärdar ett skuldebrev på 1 600 kronor. Räntor kvitteras 1902-1911."],["1920","Familjens församlingsboksutdrag visar flera åbor och hushåll inom den äldre gårdsmiljön."],["1928-11-12","Lars Emil Bengtsson erkänner under namnet Emil Bengtsson en skuld på 3 000 kronor till brodern Sven Adolf Bengtsson."],["1939-1946","Svenska Gods och Gårdar återger olika ägarlängder för Träslöv 5:3 Valagården; skillnaden är inte löst."],["1954-10-15","Alma Josefina Bengtsson avlider enligt originalutdraget ur arvskiftet."],["1955-01-12","Arvskiftet efter Alma dokumenterar syskonen, amerikanska arvingar och Lars Emil Bengtssons bosättning på Valagården."],["1958-03-25","Lars Emil Bengtsson tecknar under namnet Emil Bengtsson arrendeavtal om Träslöv 5:7 med brorsonen Harry Bengtsson."],["1958-04-01–1963-04-01","Harry Bengtsson arrenderar Träslöv 5:7 för 900 kronor per år. Emil behåller Smedlyckan bakom ladan."]],"sources":["Träslöv (N) CI:4 (1747-1798), Bild 490 / Sida 87: Anna Olofsdotters födelse 1767.","Träslöv (N) CI:4, Bild 1180 / Sida 223: Olof Anderssons och Anna Mårtensdotters vigsel 1765.","Träslöv (N) CI:4, Bild 1230 / Sida 233: Börje Pehrssons och Anna Olofsdotters vigsel 1790.","Träslöv (N) CI:4, Bild 1410 / Sida 267: Mårten Anderssons död 1762.","Träslöv (N) CI:5 (1799-1825), Bild 109 / Sida 211: Nils Bengtssons födelse 1814.","Träslöv (N) CI:5, Bild 130 / Sida 251: Anders Bengtssons födelse 1816.","Träslöv (N) CI:5, Bild 208 / Sida 407: Bengt Olofssons och Bengta Börjesdotters vigsel 1813.","Träslöv (N) AI:3 (1787-1800), Bild 85 / Sida 111: N:o 5 Jon Nilsgård.","Träslöv (N) AI:5 (1812-1829), Bild 174 / Sida 37: ''Wahlagården Jon Nilsgård''.","Himle häradsrätt FIIb:3 (1760-1789), originalsid 9: Mårten Anderssons bouppteckning 1762.","Himle häradsrätt FIIa:11 (1800-1802): Helena Jönsdotters bouppteckning 1800.","IMG_6517.HEIC, IMG_6518.HEIC och IMG_6519.HEIC: familjens gårdsanteckningar och kartavskrifter, granskade 2026-08-31.","IMG_6524.HEIC och IMG_6525.HEIC: familjeavskrift om Valagården Träslöv 5:6 och byggnadsdelningen 1866.","otydligt3.HEIC, otydligt1.HEIC och otydligt2.HEIC: kopia av Alfred Sundgrens skuldebrev 1888 och överlåtelsepåskrift 1912.","otydligt.HEIC och otydligt4.HEIC: kopia av Bengt August Nilssons skuldebrev 1901 och ränteanteckningar 1902-1911.","anteckning om sven adolf.HEIC: originalskuldebrev mellan Lars Emil och Sven Adolf Bengtsson, 1928-11-12.","Arvskifte efter Alma 1955.HEIC: originalutdrag efter Alma Josefina Bengtsson, förrättat 1955-01-12.","IMG_6532.HEIC: originalarrendekontrakt mellan Lars Emil Bengtsson och Harry Bengtsson, daterat 1958-03-25.","Leif Lundquist, Halländsk antavla 4, Hallands Släktforskarföreningen.","Hallands Släktforskarförenings gårds- och ortnamnsregister."],"uncertainties":["Familjeuppgiften om klosterhemman 1649 behöver spåras till bakomliggande originalkälla.","Swen Andersson, Inger Olsdotter och Karin Svensdotter är sekundärt knutna till gården omkring 1699-1702 och behöver verifieras i original.","1718 års anteckning om Swen Hwahl och Ingri behöver återfinnas i original.","Familjens avskrift av 1729 års landsbeskrivning behöver kontrolleras ord för ord mot originalet.","Mårten Anderssons och Helena Jönsdotters första inflyttning till Jon/Jöns Nilsgård är ännu inte fastställd.","Nils Mårtenssons uppgivna födelse på Valagård 1740 är sekundär tills födelsenotisen har kontrollerats.","Karin Börgesdotter som uppges ha avlidit på Valagård 1705 får inte sammanblandas med den 13-åriga Karin Börgesdotter i gruppen omkring 1700.","Originalkartorna 1823 och 1840 behöver identifieras för säker placering av hus och ägogränser.","Den bakomliggande källan till uppgiften om 37 personer och sex hushåll 1857 återstår.","Originalet till förrättningen 1866 behöver hittas; tolkningen att Petter Anders Svensson flyttade och Bengt August Nilsson stannade kvar är ännu inte slutbevisad.","Sambandet mellan fastighetsbeteckningarna Träslöv 5:3, 5:6 och 5:7 behöver klarläggas.","Alfred Sundgrens intecknade 3/64 mantal 1888 kan inte utan vidare likställas med Bengt August Nilssons brukningsdel.","Det exakta slutbetalningsdatumet för Bengt August Nilssons skuld är otydligt.","De två olika ägarlängderna för Träslöv 5:3 i Svenska Gods och Gårdar måste jämföras med originalutgåvorna.","Arvskiftet 1955 nämner ingen fastighet och visar därför inte i sig någon övergång av Valagården.","Arrendets fortsättning eller upphörande efter 1 april 1963 är inte känd.","Smedlyckans exakta läge bakom ladan behöver identifieras på karta.","Skillnaden mellan skuldebrevets datering 1928 och räntans startår 1920 behöver förklaras.","Amerikaspåren för Anders Gustaf, Karl Oskar och Johan Albin Bengtsson behöver beläggas med utflyttningslängder och amerikanska källor."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,area=excluded.area,latitude=excluded.latitude,longitude=excluded.longitude,visibility=excluded.visibility,content=excluded.content;
insert into public.places(id,slug,name,area,latitude,longitude,visibility,content) values('skultagarden','skultagarden','Skultagården','Träslöv',null,null,'public','{"id":"skultagarden","name":"Skultagården","area":"Träslöv","aliases":["Skultagården","Skultagård","N:o 39 Skultagården"],"note":"Separat men närliggande gårdsmiljö till Valagården. Helena Jönsdotter anges som piga från Skultagården vid vigseln 1731, och Jöns Polin förekommer sannolikt som fadder i Skultagårdsmaterialet redan 1704.","facts":[["Gårdsidentitet","Originalsidan är rubricerad N:o 39 Skultagården och ska hållas åtskild från Valagården utan särskilt källstöd."],["Nutida uppgift","Användaren uppger att Skultagården är närliggande Valagården och finns kvar än idag."],["Tidigt hushåll","Gården visar bland annat Börge Andersson, Inger Larsdotter, Lars Jönsson, Börta/Brita Börgesdotter och flera barn i äldre hushållsmiljö."],["Polin-spår","Jöns Polin läses med hög sannolikhet som fadder/vittne i en kristningsnotis 1704-07-10."],["Direkt släktkoppling","Helena Jönsdotter, dotter till Jöns Polin och Karin Helgesdotter, anges som piga från Skultagården vid vigseln 1731."]],"story":["Skultagården är en egen gårdsmiljö i Träslöv och ska inte blandas ihop med Valagården/Wahlagården. V102 gör denna åtskillnad viktig, eftersom flera personer rör sig i samma lokala nätverk utan att gårdarna därför blir samma plats.","Gårdssidan innehåller hushålls- och åldersuppgifter samt löpande notiser om dop, vigslar och begravningar från omkring 1690 till 1713. Den visar en äldre Börge-, Lars- och Jöns-miljö innan Polin-kopplingen blir tydlig.","Det mest intressanta Polin-spåret är 1704-07-10, där Jöns Polin sannolikt förekommer som fadder eller vittne i Skultagårdens material. Det bevisar inte att han bodde där, men visar sannolikt att han ingick i gårdens sociala nätverk redan året före vigseln med Karin Helgesdotter.","Skultagården blir senare viktig genom att Helena Jönsdotter anges som piga därifrån när hon gifter sig med Mårten Andersson 1731. Kopplingen mellan Helge Svenssons familj, Polin-familjen och Skultagården ska därför fortsätta följas kronologiskt."],"timeline":[["1690-05-05","Notis som mycket sannolikt avser en vigsel för Börge Andersson."],["1691-01-18","Kristningsnotis för Börge Anderssons barn i Skultagården."],["1692-11-23","Begravningsnotis som sannolikt avser Lars Jönsson."],["1693-10-29","Mycket sannolik vigselnotis för Anders Larsson."],["1704-07-10","Jöns Polin förekommer sannolikt som fadder/vittne i en kristningsnotis knuten till gården."],["1713-02-22","Ytterligare gårdsnotis, delvis svårläst och ännu inte övertolkad."],["1731-04-25","Helena Jönsdotter anges som piga från Skultagården vid vigseln med Mårten Andersson."]]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,area=excluded.area,latitude=excluded.latitude,longitude=excluded.longitude,visibility=excluded.visibility,content=excluded.content;
insert into public.places(id,slug,name,area,latitude,longitude,visibility,content) values('lars_trulsgard','lars-trulsgard','Lars Trulsgård','Träslöv',null,null,'public','{"id":"lars_trulsgard","name":"Lars Trulsgård","area":"Träslöv","aliases":["Lars Trulsgård","Lars Truelsgård"],"note":"Jöns/Jonas Andersson Polin knyts i dödsnotisen till Lars Trulsgård i Träslöv."}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,area=excluded.area,latitude=excluded.latitude,longitude=excluded.longitude,visibility=excluded.visibility,content=excluded.content;
insert into public.places(id,slug,name,area,latitude,longitude,visibility,content) values('klockaregarden','klockaregarden','Klockaregården','Träslöv nr 1',null,null,'public','{"id":"klockaregarden","name":"Klockaregården","area":"Träslöv nr 1","aliases":["Klockaregården","Klockargården","Lars Tungård","Träslöv 1","Träslöv nr 1"],"relatedPersonIds":["jons_polin_1682","karin_helgesdotter_1685","beata_jonsdotter_polin","helena_jonsdotter_1713","petter_jonsson_polin","kerstin_jonsdotter_polin_1725","anna_jonsdotter_polin_1728"],"note":"Klockaregården är en egen gård i Träslöv nr 1, även kallad Lars Tungård. Gården är det viktigaste platsspåret för klockaren Jöns Andersson Polin och hans familj, men deras exakta bosättning där är ännu inte slutligt originalbekräftad.","facts":[["Gårdsidentitet","Hallands Släktforskarförenings gårdsregister anger Träslöv nr 1 = Lars Tungård, med bruksnamnet Klockaregården."],["Viktig åtskillnad","Klockaregården och Prästgården är två olika platser. Kyrkobokens innehållsförteckning samlar material från båda i ett gemensamt specialavsnitt, men det gör dem inte till samma gård."],["Polin-koppling","Jöns Andersson Polin kom till klockaretjänsten i Träslöv 1703. Gården är därför ett naturligt men ännu inte slutbevisat bostadsspår för familjen."],["Arbetsperiod","Den viktigaste perioden att kartlägga är 1704-1715 och därefter fram till att Jöns lämnade tjänsten efter 1747."],["Mantalslängd 1731","Det första gårdsblocket i Träslövs mantalslängd förefaller motsvara Klockaregården, men namnen är ännu för svårlästa för att Jöns Polin ska identifieras säkert där."],["Kyrkoboksavsnitt","Ett särskilt födelse- och dödboksavsnitt gäller Klockaregården samt den separata Prästgården. Senare närbilder visar starka Polin-familjeposter."],["Polin-familjen","Beata 1707, Helena 1713 och Petter 1721 är starka poster. Kerstin/Kirsti 1725 och Anna 1728 är sannolika sidospår med lägre säkerhet."],["J. A. Polin 1707","Signaturen ''Finis hujus Anni. J. A. Polin'' vid årets slut är ett mycket starkt spår efter Jöns Andersson Polin och hans kyrkliga skrivarroll."],["Faddermiljö","Nätverket omfattar Varberg, Lunden, Klastorp och möjliga Polin/Bolin-personer som Lars, Agneta och Greta."],["N:o 38-korrigering","N:o 38 är Börge Anders hemman och får inte användas som synonym för Klockaregården. Klockaregården ska sökas genom gårdsnamnet, Träslöv nr 1, klockartiteln eller annan oberoende uppgift."],["Källstatus","Gårdsidentiteten Träslöv nr 1/Lars Tungård/Klockaregården stöds av gårdsregistret. Polin-familjens exakta boende och flera fadderläsningar behöver fortsatt originalkontroll."]],"story":["Klockaregården är en egen gård i Träslöv och ska hållas helt åtskild från Prästgården. Gårdsregistret identifierar Träslöv nr 1 som Lars Tungård med bruksnamnet Klockaregården. Ett original där namnformerna står sida vid sida bör fortfarande jämföras, men identifikationen är betydligt starkare än den äldre hypotesen kring N:o 38.","Gården är central för Polin-forskningen eftersom Jöns eller Jonas Andersson Polin kom till klockaretjänsten i Träslöv 1703. Efter vigseln med Karin Helgesdotter 1705 kan Klockaregården ha blivit familjens tjänste- eller bostadsmiljö. Det är ännu inte slutligt bevisat att hela familjen bodde där, så personkopplingen ska beskrivas som starkt platsspår snarare än säker bostadsadress.","Bokens innehållsförteckning pekar ut ett särskilt kyrkoboksavsnitt för Klockaregården samt Prästgården. Det betyder att källmaterial från två olika platser har samlats i samma avsnitt. En enskild notis får därför inte automatiskt tillskrivas Klockaregården utan att text, titel, person eller annan omständighet visar det.","Senare och tydligare närbilder har korrigerat det äldre forskningsläget. Beata Polins födelse den 15 april och dop den 17 april 1707 är nu en mycket stark originalkandidat. Helena Jönsdotters födelse natten mellan 6 och 7 oktober och dop den 8 oktober 1713 är en direkt originalkälla till huvudlinjen. Petters post 1721 är också stark, medan Kerstin/Kirsti 1725 och Anna 1728 förs mer försiktigt.","Vid slutet av 1707 års kyrkoboksanteckningar står sannolikt ''Finis hujus Anni. J. A. Polin''. Initialerna och det ovanliga namnet passar Jöns Andersson Polin mycket väl. Signaturen kan vara hans egen och antyder att han deltog i kyrkobokens förande eller sammanställning, men exakt hand och arbetsinsats är ännu inte absolut bevisade.","Fadderkretsen ger gårdsmiljön ett större socialt sammanhang. Lars Polin förekommer sannolikt vid Beatas dop 1707. Vid Helenas dop 1713 syns bland andra Jöns Grimberg, Mathias Höök, Olof Börgesson i Lunden, Anders Gillberg/Cillberg och Elisabet Bruhn samt personer från Varberg. År 1721 återkommer Klastorp, Lunden och möjliga Greta eller andra Polin/Paulin-personer.","Mantalslängden 1731 är viktig eftersom gårdsföljden sannolikt börjar med Träslöv nr 1 Klockaregården. Namnen i det första blocket är dock ännu för svårlästa för att Jöns ska föras in som säker boende. Jämförelse med 1730 och 1732 kan visa vem som brukade gården och hur tjänste- eller hushållsrollen förändrades.","En tidigare arbetsidé försökte koppla N:o 38 till Klockaregården. Den är korrigerad: N:o 38 är Börge Anders hemman och hör till ett annat gårdsspår. Klockaregården ska följas separat genom Lars Tungård, Träslöv nr 1, klockartiteln och Polin-familjens uttryckliga källspår."],"timeline":[["1703","Jöns Andersson Polin kommer till klockaretjänsten i Träslöv."],["1704-07-10","Jöns Polin förekommer sannolikt som fadder vid Skultagården. Det visar ett tidigt lokalt nätverk men inte bosättning på Klockaregården."],["1705-03-19","Jöns Polin och Karin Helgesdotter vigs. Tiden därefter är prioriterad för att fastställa familjens eventuella bosättning på Klockaregården."],["1707-04-15/17","Mycket stark post för dottern Beatas födelse och dop i specialavsnittet."],["1707","Året avslutas med den sannolika signaturen ''J. A. Polin'', ett starkt indicium på Jöns kyrkliga skrivarroll."],["1713-10-06/08","Helena Jönsdotter föds under natten mellan 6 och 7 oktober och döps 8 oktober som klockarens dotter."],["1721-10-31/11-05","Stark post för sonen Petters födelse och dop; sekundärmaterial placerar honom vid Klockaregården."],["1725-08-12/15","Sannolik post för dottern Kerstin/Kirsti. Möjlig Mårten Andersson i fadderlistan är ännu obekräftad."],["1728-01-21/26","Dottern Anna föds och döps i den fortsatta kyrkliga miljön."],["1731","Mantalslängdens första gårdsblock förefaller avse Klockaregården, men Jöns Polin är ännu inte säkert läst där."],["efter 1747","Jöns lämnar klockaretjänsten till mågen Bengt Ehn."],["1758-05-24","Jöns Polin dör; dödsnotisen beskriver sannolikt hans gravplats vid Träslövs kyrka."]],"sources":["Hallands Släktforskarförenings gårdsregister: Träslöv nr 1 = Lars Tungård, bruksnamn Klockaregården.","Träslövs mantalslängd 1731, gårdsföljden omkring sidorna 700-701; första gårdsblocket behöver fortsatt transkription.","Träslövs kyrkoboks specialavsnitt för Klockaregården samt Prästgården, med granskade poster 1701-1728.","Externt ortnamnsregister till 50 halländska antavlor, med Beata Jönsdotter Polin och Petter Jönsson Polin placerade vid Träslöv Klockaregården.","Jöns Andersson Polins vigselnotis 1705, Helenas födelse- och dopnotis 1713 samt Jöns dödsnotis 1758."],"uncertainties":["Klockaregården och Prästgården är olika platser; poster i deras gemensamt rubricerade kyrkoboksavsnitt måste fördelas källkritiskt.","Ett original som uttryckligen visar namnformerna Lars Tungård och Klockaregården sida vid sida bör fortfarande kontrolleras.","Jöns och Karin är ännu inte slutligt originalbelagda som boende på Klockaregården trots den starka yrkes- och familjekopplingen.","N:o 38 får inte kopplas till Klockaregården; det är Börge Anders hemman.","Lars Polins släktskap med Jöns samt läsningarna Agneta Polin, Greta Polin och ytterligare Polin/Paulin-personer är inte bekräftade.","Den möjliga Mårten Andersson i 1725 års fadderlista behöver prioriterad omläsning."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,area=excluded.area,latitude=excluded.latitude,longitude=excluded.longitude,visibility=excluded.visibility,content=excluded.content;
insert into public.places(id,slug,name,area,latitude,longitude,visibility,content) values('prastgarden','prastgarden','Prästgården','Träslöv',null,null,'public','{"id":"prastgarden","name":"Prästgården","area":"Träslöv","aliases":["Prästgården","Träslövs prästgård"],"relatedPersonIds":[],"note":"Prästgården är en egen plats och ska inte blandas ihop med Klockaregården. Kyrkobokens innehållsförteckning samlar födelse- och dödboksmaterial från båda platserna i ett gemensamt specialavsnitt.","facts":[["Viktig åtskillnad","Prästgården och Klockaregården är två olika platser."],["Källstruktur","Bokens innehållsförteckning rubricerar ett specialavsnitt för Klockaregården samt Prästgården, vilket förklarar varför poster från kyrklig och ämbetsmannamässig miljö förekommer tillsammans."],["Miljö","Materialet innehåller bland annat familjen Brinck, Lars Dahlberg, kyrkliga eller militära titlar och långa fadderlistor med personer från Varberg."],["Pastorat","Träslöv hörde under perioden samman med Varbergs slottsförsamling i samma pastorat."],["Källstatus","Enskilda poster måste läsas innan de kan föras till antingen Prästgården eller Klockaregården."]],"story":["Prästgården är en separat plats i Träslöv. Den har tidigare råkat ligga ihop med Klockaregården i webbplatsens platskort eftersom kyrkobokens innehållsförteckning har ett gemensamt specialavsnitt för de båda miljöerna.","De tidiga granskade sidorna från 1701-1711 innehåller högrestånds-, kyrkliga och ämbetsmannamässiga personer, bland annat Olof Brinck och Lars Dahlberg, samt omfattande fadderkretsar från Varberg. Det passar en prästgårds- och pastoratsmiljö, men varje notis behöver fördelas till rätt plats innan den används som gårdshistoria.","Polin-familjens starka poster ligger kvar som forskningsmaterial i samma källavsnitt, men deras koppling presenteras på Klockaregårdens sida. Det gemensamma bokavsnittet får inte användas som bevis för att Klockaregården och Prästgården var samma plats."],"timeline":[["1701-07-27","Lång notis i specialavsnittet med Olof/Oluf Brinck och omfattande fadderlista."],["1703-05-31","Längre notis ur kyrklig eller ämbetsmannamässig miljö."],["1706","Notis där Lars Dahlberg förekommer."],["1707-07-25","Ytterligare notis utan säker Polin-identifikation."],["1709-06-30","Post med omfattande namn- och fadderuppgifter."],["1711-02-24","Post i samma specialavsnitt; platsfördelningen behöver fortsatt källkontroll."]],"uncertainties":["Det är ännu inte avgjort vilka enskilda poster i det gemensamma specialavsnittet som hör till Prästgården respektive Klockaregården.","Prästgårdens exakta historiska läge och gårdsidentitet är ännu inte kartlagda i projektet."]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,area=excluded.area,latitude=excluded.latitude,longitude=excluded.longitude,visibility=excluded.visibility,content=excluded.content;
insert into public.places(id,slug,name,area,latitude,longitude,visibility,content) values('nils_olsgard','nils-olsgard-niels-olufs-hemman','Nils Olsgård / Niels Olufs Hemman','Träslöv nr 4 / N:o 26',null,null,'public','{"id":"nils_olsgard","name":"Nils Olsgård / Niels Olufs Hemman","area":"Träslöv nr 4 / N:o 26","aliases":["Nils Olsgård","Nils Ols gård","Träslöv nr 4","Niels Olufs Hemman","N:o 26 Niels Olufs Hemman","Niels Olufs Hemman i Träslöf"],"note":"Mycket viktigt originalspår för Karin Helgesdotters barndomsmiljö. V102 placerar med hög sannolikhet Helge Svensson, Kerstin Olsdotter och barnen, inklusive Karin, i ett hushåll på N:o 26 Niels Olufs Hemman.","facts":[["Originalrubrik","N:o 26 Niels Olufs Hemman i Träslöf."],["Modern/arbetsform","Nils Olsgård / Nils Ols gård."],["Direkt linje","Helge Svensson + Kerstin Olsdotter → Karin Helgesdotter → Helena Jönsdotter."],["Hushåll","Helge Svensson ca 40 år, Kerstin/Kirstin Olsdotter ca 46 år, Olof Helgesson, Simon Helgesson, Inger Helgesdotter, sannolikt Margareta Helgesdotter, Anders Helgesson och Karin Helgesdotter ca 4 år."],["Källstatus","Mycket starkt originalfynd för gårdsmiljön; enskilda åldrar och läsningar bör fortsatt behandlas som ungefärliga."]],"story":["Nils Olsgård, i äldre form N:o 26 Niels Olufs Hemman, är nu en av de viktigaste platserna i morfarslinjens äldre del. V102 visar ett hushåll som med hög sannolikhet innehåller Helge Svensson, Kerstin Olsdotter och deras barn, däribland Karin Helgesdotter.","Det gör gården till Karins sannolika barndomsmiljö innan hon 1705 gifter sig med Jöns Andersson Polin. Samtidigt ska den senare Skultagårdskopplingen hållas åtskild: arbetsbilden är att familjen först hör till Nils Olsgård och att kopplingen till Skultagården blir tydligare senare.","De löpande notiserna från 1690-1701 visar också att gården var en levande miljö med flera hushåll, dop, begravningar och möjliga vigsel- eller familjehändelser. Alla personer där ska inte automatiskt räknas som släkt, men de kan bli viktiga för framtida nätverksanalys."],"timeline":[["ca 1690","Hushållet med Helge Svensson, Kerstin Olsdotter och barnen, inklusive Karin ca 4 år, hör sannolikt hemma på N:o 26."],["1690-08-31","Begravningsnotis på gårdssidan, namnrelationen ännu preliminär."],["1694-12-28","Ytterligare begravningsnotis knuten till gårdsmiljön."],["1697-10-24","Begravning av en Anders, omkring 31 år; relation till direktlinjen ej fastställd."],["1698-12-26","Möjlig vigsel- eller familjenotis som behöver bättre bild/parallellkälla."],["1699-11-05","Begravning av barn, sannolikt knutet till Hans Nilsson/Nielsson."],["1700-09-23","Kristningsnotis där Nils/Niels barn Bengt kan läsas."],["1701-05-26","Begravning av ett barn med namnet Bengt knutet till Nils/Niels-familj."]]}'::jsonb) on conflict(id) do update set slug=excluded.slug,name=excluded.name,area=excluded.area,latitude=excluded.latitude,longitude=excluded.longitude,visibility=excluded.visibility,content=excluded.content;
